-- ============================================================
-- Qazax8 — "Anacan" MÜRACİƏTİNİN lokallaşdırılması
--   kk → Анашым · ru → мамочка · tr → anneciğim (brend adları toxunulmur)
-- Əhatə: pregnancy_daily_content.baby_message_{kk,ru,tr} (körpənin anaya mesajları)
--        + 2 dashboard UI açarı (kk).
-- Cəmi: 384 content UPDATE + 2 UI upsert.
-- ============================================================


INSERT INTO public.translations (key, lang, value, namespace) VALUES ('dashboard_hero_fruit_tpl', 'kk', 'Анашым, қазір менің өлшемім {fruit} сияқты', 'common')
ON CONFLICT (key, lang) DO UPDATE SET value = EXCLUDED.value;

INSERT INTO public.translations (key, lang, value, namespace) VALUES ('dashboard_anacan_hazirda_cfaa50', 'kk', 'Анашым, қазір', 'common')
ON CONFLICT (key, lang) DO UPDATE SET value = EXCLUDED.value;

UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, Сізге бір құпия айтайын ба? 🤫 Денеңіздегі мыңдаған жасушаның бірі дәл "МЕН" болу үшін жарысқа түсті! Ол қазір өздігінен өсіп, әкемнен келетін екінші жартысымен кездесетін күнді асыға күтіп жүр. Біздің сол үлкен кездесуімізге шамамен 1 апта қалды. Мен қатты толқып жүрмін, ал Сіз ше? Сіздің жылы құшағыңызды сағындым.' WHERE id = 'cf28e232-185c-40c5-9616-39e6df91cf1f';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Сәлем, анашым! ❤️ Денеңде үлкен толқу барын сезіп тұрсың ба? Бір мерекеге дайындық жүріп жатқандай. Эстроген гормоның шарықтау шегіне жетіп келеді, бұл сол "алтын жұмыртқаның" (яғни менің жартымның) жолға шығуға дайын екенін білдіреді. Сен тек өзіңе жақсы күтім жасап, мол су ішіп, демал. Мен сені таңдауға асығып жүрмін. Әкеме де дайын болсын деп айт, кездесуімізге өте аз уақыт қалды! Мен сендердің махаббаттарыңның ең әдемі дәлелі болу үшін келемін.' WHERE id = '3b975bc1-895c-42e8-be4c-f6d56b176b19';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Білемін, сен мені әлі көрмейсің, бірақ сахна сыртындағы шамдар жағылып жатыр. 🌟 Денең мен үшін ең жұмсақ төсек — эндометрийді дайындай бастады. Әкемнің жасушалары да жолға шығып, мені іздеп келе жатқан шығар. Сенің жылуың мен қамқорлығың маған қазірдің өзінде күш береді. Біздің хикаямыз басталғалы тұр, анашым. Сен тек сеніміңді жоғалтпай, күлімдей бер, өйткені ғажайыптар сенген кезде орындалады. Сен менің қаһарманымсың!' WHERE id = '29e7920b-060e-4fac-ad72-d19dda159289';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, бұл күндер Сіз үшін аздап ауыр әрі шаршататын болуы мүмкін екенін білемін, бірақ Сіз өте мықтысыз. 😔 Ағзаңыздағы осы тазалану үдерісі менің болашақтағы жайлылығым үшін екенін ұмытпаңыз. Мен келгенде бәрі тап-таза әрі жұмсақ болуы үшін Сіз менің алғашқы үйімді, ұямды — жатырыңызды дайындап жатырсыз! Сіз сезінген әрбір жайсыздық — біздің қауышуымызға қарай жасалған бір қадам. Өтінемін, бүгін өзіңізді шаршатпай, аяғыңызды созып, демалыңыз. Мен Сізді сеземін және Сізге күш жіберемін!' WHERE id = '1b683a24-ae16-485e-bf86-c173f0a5ad7a';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Әкеммен қалай танысқаныңызды елестетемін... 💭 Мен Сіздердің сол үлкен махаббаттарыңыздың ең әдемі жемісі боламын. Ағзаңыз мені қарсы алу үшін бар күшін салып, бәрі мінсіз болуы үшін әрбір ұсақ-түйекке дейін жоспарлап жатыр. Мен әзірге жұлдыз тозаңындаймын, әлі физикалық болмысым жоқ, бірақ Сіздің махаббатыңыз мені өмірге шақырып тұр. Қазір өзіңізге қаншалықты жақсы қарасаңыз, мен де соншалықты дені сау болып келемін. Біздің хикаямыз өте әдемі болады, анашым!' WHERE id = 'c852b157-989c-44ce-a4ea-0f5d022c7159';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Бүгін айнаға қарағанда міндетті түрде жымиыңыз! 😊 Өйткені ағзаңыз ғажайып жұмыс атқарып, жаңа өмірді дүниеге әкелуге дайындалып жатыр. Біз әлі физикалық тұрғыдан қосылмасақ та, рухани тұрғыдан бір-бірімізбен байланыстымыз. Мен Сізді, ал Сіз мені таңдадыңыз. Ағзаңыз менің келуіме, сол ғажайып кездесуге (ұрықтануға) күн сайын бір қадам жақындап келеді. Мен Сізге сенемін, анашым!' WHERE id = 'e510f21d-5c69-49bc-a4d8-ea262a0bda7b';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Сәлем! Бүгін ішіңізде жаңа көктем басталғандай сезіледі, солай емес пе? 🌱 Шын мәнінде, дәл солай! Аналық бездеріңіздің бірінде кішкентай "мен" оянып, өсуге талпынып жатырмын. Мен әзірге жалғыз ғана жасушамын, бірақ Сіздің бір бөлшегіңізбін. Сіз бақытты болып, күлген сайын мен де күшейе түсемін. Өзіңізді күтіңіз, анашым, өйткені Сіз — менің болашағымсыз!' WHERE id = '367c8044-41d2-441f-8aec-78399bc382c5';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен сапарға шықтым, анашым! 🎒 Қазір жатыр түтігіндемін және Сіздің жылы ұяңызға (жатырыңызға) қарай домалап барамын. Қолым бос емес, әр бірнеше сағат сайын бөлінемін: 2 едім, 4 болдым, кейін 8 боламын! Сіз әзірге ештеңе сезбейсіз, бірақ ішіңізде жаңа өмір қайнап жатыр. Маған сәттілік тілеңіз, жолым ұзақ, бірақ мен өте табандымын. Сізге жету үшін бәрін жасаймын!' WHERE id = 'c870b9dc-4e80-4fec-9e7f-794942ed46c8';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Үйге жетуге аз қалды! 🏠 Жатыр түтігіндегі сапарым аяқталуға жақын. Сіздің жатырыңызды көріп тұрмын! Ол сондай жайлы, жұмсақ әрі нәрлі көрінеді... Өзіме орын таңдауға дайындалып жатырмын. Мен әлі де қабығымның ішіндемін, бірақ жақында одан шығамын. Сіз мен үшін дүниедегі ең қауіпсіз мекенсіз. Мені қорғаймын деп уәде беріңіз, анашым.' WHERE id = 'fb5dbb9e-d8ba-40b0-8cd3-d9a67a57068c';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Деміңізді ішке тартыңыз, анашым! 🌬️ Ұлы сәт жақындап қалды. Сіздің ғажайып аналық жасушаңыз босап шығуға дайын. Бұл — біздің хикаямыздың «Баяғыда бір заманда...» деп басталатын тұсы. Мен әлі пайда болмасам да, Сіз бен әкемнің махаббаты мені шақырып тұр. Денеңіз мен үшін ең мінсіз ортаны жасап қойды, бәрі сағаттай дәл жұмыс істеп тұр. Дайынсыз деп үміттенемін, өйткені мен келе жатырмын! Сіздің құшағыңыз менің алғашқы Отаным болады.' WHERE id = '0c974e6a-8f9e-4c84-9656-5142174149f9';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, бүгін мен үшін еркіндік күні! 🐣 Осы уақытқа дейін мені қорғап келген қалың қабығымнан (zona pellucida) шығып жатырмын. Мұны «Hatching» (қабықтан шығу) деп атайды. Сіздің жұмсақ қабырғаңызға тікелей тиіп, бекінуім үшін осылай істеуім керек. Мен дайынмын, ал Сіз дайынсыз ба? Есікті ашыңыз, мен келе жатырмын!' WHERE id = '5b11fc22-b976-4d28-ade3-c7ba82a43750';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, бүгін — сол ұлы күн! Өмірімдегі ең маңызды сәттердің бірі... ❤️ Енді мен Сізге тиіп тұрмын. Ұзақ сапардан кейін ақыры үйімнің қабырғасына жеттім. Мұнда сондай жылы, сондай жұмсақ әрі сондай қауіпсіз... 9 ай бойы Сізден ажырамау үшін бар күшіммен осы жерге бекініп жатырмын. Бұл — біздің алғашқы құшағымыз, анашым. Мені сезіп тұрсыз ба? Мен Сізбен біргемін, енді ешқайда кетпеймін. Біздің хикаямыз дәл осы жерден шын мәнінде басталады.' WHERE id = '11de56c7-f131-4d7f-8640-81f988697e07';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен одан әрі тереңдеп барамын, анашым! 🧱 Кеше жай ғана жанасқан едім, ал бүгін сенің жұмсақ қабырғаңның ішіне қарай еніп келемін. Бұл өзімді үңгір қазып жүрген зерттеушідей сезіндіреді. Өзіме жылы әрі қауіпсіз ұя жасап жатырмын. Әр сәт сайын сенімен тұтасып, сенің бір бөлшегіңе айналып келемін. Енді біз жай ғана "сен және мен" емеспіз, енді біз — "БІЗБІЗ". Бұл сезім маған қатты ұнайды! Сен менің қамалымсың, панамсың әрі бүкіл әлемімсің.' WHERE id = 'ba359509-7778-4e6b-9433-e5179d225ea1';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, саған арналған ерекше хабарым бар! 🤫 Бұл — екеуміздің алғашқы құпиямыз. Ағзаңа менің бар екенімді білдіретін арнайы химиялық белгі жібере бастадым. Бұл белгі: "Мен осындамын, анашым! Бәрі жақсы. Ағзаңды мен үшін дайындауды жалғастыра бер", — дейді. Енді сенімен өз тілімде сөйлесе аламын. Бұл — арамыздағы көзге көрінбейтін байланыс, ол күн сайын нығая түседі.' WHERE id = '17afd972-48a8-4084-ba7e-669ef6162afc';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Ұямның дәл ортасындамын, анашым! 🩸 Бұл жер сондай жайлы... Сенің қан тамырларыңа жақындап, енді тікелей сенен қоректене бастадым. Маған жіберген әрбір түйірің, әрбір тамшың мені өсіріп, күш береді. Бұл — әлемдегі ең дәмді ас, өйткені ол махаббатқа толы. Сенің арқаңда өсіп келемін, сенің арқаңда бармын. Көп рақмет, анашым!' WHERE id = 'cb0cb4a0-60ab-4796-9f3a-e0d285d2a27e';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, мен әлі өте кішкентаймын, күнжіт дәніндей ғанамын, бірақ менің үлкен жоспарларым бар. Қазір пішінім жалпақ, алайда көп ұзамай иіліп, сүйкімді "C" пішініне енемін. Сенің құрсағың — менің үйім, ал жүрегің — менің панам. Біздің 9 айлық сапарымыз бүгіннен бастап ресми түрде басталады!' WHERE id = 'd1b2e180-b513-41eb-8922-8f2b0c7d3ee8';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Менің кішкентай тамырларым пайда болып жатыр, анашым! 🌳 Әрине, бұлар қол саусақтары емес. Бұлар сенің сол жылы қабырғаңа бұрынғыдан да берік жабысуыма көмектесетін ерекше өсінділер (хорион бүрлері). Солардың арқасында саған мықтап құшақтасып, сенен көбірек қорек аламын. Мен мұнда өзіме берік қамал салып жатырмын, ал оның әр кірпіші екеуіміздің махаббатымыздан қалануда. Мені ешқашан жіберме, жарай ма? 🤞' WHERE id = '101fd61b-d3d7-4f5b-8f09-77163d30e4ea';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Ұямның есігі енді артымнан жабылып келеді, анашым! 🚪 Мен толығымен ішке орналастым, Сіздің жылы әрі қауіпсіз әлеміңіз мені жан-жағымнан қоршап тұр. Енді мен Сіздің ажырамас бір бөлшегіңізбін. Бұл — біздің оқиғамыздың жай ғана басталуы емес, ортақ өміріміздің алғашқы күндері. Мен Сізді таңдадым, ал Сіз мені қорғап жүрсіз. Бұдан кейін бәрі одан сайын ғажайып болады! Біз бірге керемет шытырман оқиғаға дайынбыз! 🥳' WHERE id = 'f77ae8b4-6a1d-4c99-abe2-93a350b86318';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, арамыздағы байланыс одан сайын нығайып келеді! 🧬 Енді мен Сіздің ағзаңызбен тікелей байланыстамын. Қаныңыздан келген әрбір бөлшекпен тыныстап жатқандаймын. Бұл — менің алғашқы қан айналымым, өмірдегі алғашқы тынысым. Енді біз бір тамырмен ағып, бір ырғақпен өмір сүріп жатырмыз. Маған жіберген әрбір қоректік затыңыз бен әрбір оттегі молекуласы мені өсіреді. Бұл — әлемдегі ең ғажайып сезім: Сізбен біртұтас болу. ❤️' WHERE id = '3ebbef70-38c5-48c1-9efc-c1f2707c71d4';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, мен енді жалпақ дискіге ұқсаймын! 💿 Мен өте маңызды екі қабаттан тұрамын. Біреуі менің басымды, денемді, қолдарым мен аяқтарымды қалыптастырады. Ал екіншісі осы жолда маған көмектесіп, мені қоректендіреді. Бұл — денемнің алғашқы жоспары, алғашқы сәулеттік сызбам. Барлығы осы екі қабаттан басталады. Маған сенесіз бе? Мен ғажайып туынды боламын, өйткені менің сәулетшім — Сіз. ✨' WHERE id = '4a43f3bd-ef22-4f54-b8c8-fd8abe1f9de2';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Бүгін мен үшін төңкеріс күні, анашым! 🚀 Менің жалпақ дискімнің үстінде ерекше бір сызық, жол пайда болып жатыр. Бұл сызық — менің болашақ картам. Ол омыртқамның, басым мен аяқтарымның қай жерде орналасатынын көрсететін бағдар болады. Осы сызықтың арқасында менің оң және сол жағым қалыптасады. Енді мен ретсіз диск емеспін, мен симметриялы, белгілі бір жоспармен дамып келе жатқан тіршілік иесімін. Сен менің сәулетшімсің, ал мен сенің жауһарыңмын. Бәрі енді басталады! 🤩' WHERE id = 'aeee39a9-79a9-4e00-b2e5-3d55b7831226';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Жасушаларым үлкен көшті бастады, анашым! 🚶‍♂️ Мыңдаған кішкентай жұмысшы кеше пайда болған ерекше сызықтың ішіне қарай ағылып, мен үшін жаңа қабаттар салып жатқандай. Олар үш түрлі топ құрады: Эктодерма, Мезодерма және Эндодерма. Біріншісі менің терімді, шашымды және миымды, екіншісі жүрегімді, қанымды және сүйектерімді, ал үшіншісі асқазаным мен өкпемді қалыптастырады. Мен сәулетші секілді өзімді өзім құрып жатырмын, анашым. Іргетасымды қалап жатырмын. Бұл іргетас өте берік болады, өйткені сен менің жанымдасың. 💪' WHERE id = '93c5c870-b03a-45f8-92da-cc13e151719b';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, бүгін менің алғашқы омыртқамның іргетасы қаланып жатыр! 🦴 Бұл әзірге сүйек емес, бірақ болашақта мені тік ұстап, бүкіл денеме пішін беретін ерекше, иілгіш өзек (нотохорд). Бұл өзек бүкіл денеме қолбасшы секілді «Енді өсіп, қалыптасатын уақыт келді!» деп бұйрық береді. Қалған барлық ағзам соның айналасында орналасады. Енді мен жай ғана диск емеспін, менің орталығым және бағытым бар. Бәрі неткен мінсіз жоспарланған, солай емес пе? 🥰' WHERE id = '8f493a1c-c305-477a-b7ce-1bad294f04bc';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Миымның алғашқы жасушалары пайда болып жатыр, анашым! 🧠 Менің сыртқы қабатым нотохорд деп аталатын жетекшімнен белгі алып, қалыңдайды да, ерекше пластинка түзеді. Бұл пластинка — менің бүкіл болашағым: одан жүйке жүйем, ойларым, армандарым мен сезімдерім пайда болады. Сізді жақсы көруді, Сізді сезінуді үйренетін ғажайып миымның негізі бүгін қалана бастайды. Сіз туралы қазірдің өзінде ойлай бастадым... 💭' WHERE id = '43fe1f43-aa40-4388-8525-495fa2d86771';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Менің жүйке пластинкам ішке қарай бүктеліп жатыр, анашым. Бұл қағаз парағын абайлап орап, түтік жасағандай. 📜 Осы түтік менің жұлын жүйеме айналып, бүкіл денеме тіршілік нәрін береді. Барлығы сондай жылдам әрі дәл жүріп жатыр! Бәрі дұрыс қалыптасуы үшін бар күшімді салып жатырмын. Бұл үдерісте Сіздің махаббатыңыз бен қамқорлығыңыз — мен үшін ең үлкен демеу. Мен үшін алаңдамаңыз, бәрі жоспар бойынша жүріп жатыр.' WHERE id = 'b41d3e4c-6e83-438c-ac67-3bae19895608';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, жүрегім соғуға дайындалып жатыр! ❤️ Денемнің ортаңғы қабатындағы ерекше жасушалар бірігіп, екі жіңішке кішкентай түтік түзуде. Бұл түтіктер жақында бір-біріне жақындап, қосылады да, менің алғашқы жүрегімді қалыптастырады. Ол әлі соғып тұрған жоқ, бірақ дайындалып жатыр. Сіз үшін, Сіздің шексіз махаббатыңызбен соғатын жүрек... Бірнеше күннен кейін менің алғашқы жүрек соғысымды естисіз. Бұл біздің махаббат әніміз болады. 🎶' WHERE id = 'a58decf1-baad-47a3-bbda-0f37f307566e';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, бүгін ғажайып сәт болып жатыр! 🎻 Әлгі екі жүрек түтігі бүгін бір-бірімен қосылып, менің алғашқы біртұтас жүрегімді қалыптастырады. Оның әзірге толық қуыстары жоқ, ол тек соғуға дайындалып жатқан түтік қана. Бірақ ол менің бүкіл болашақ өмірімнің орталығы әрі ырғағы болады. Ол соға бастағанда, бүкіл ғалам үнсіз қалып, біздің әнімізді тыңдайтынын біліңіз. Бұл менің Сізге арналған алғашқы серенадам болады.' WHERE id = '4937b5d7-78ca-4fd1-9c67-7e6fd29ba696';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Соғып тұрмын, анашым... Соғып тұрмын! 💓 Бүгін менің кішкентай жүрегім алғаш рет өздігінен соқты. Бұл — Сіз үшін, біз үшін, махаббатымыз үшін соғатын ырғақ. Әзірге ол өте әлсіз, тіпті ультрадыбыстық зерттеу кезінде оны көрмеуіңіз мүмкін, бірақ мен оның соғып тұрғанын білемін. Осылайша мен Сізге "Мен тірімін, мен осындамын!" деп айтып тұрмын. Бұл — біздің махаббат әніміздің алғашқы нотасы, ол бүкіл өміріміз бойы жалғасады. 🎼' WHERE id = 'ba2ff002-749c-48f9-ae06-18528b825ab3';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен енді жалпақ емеспін, анашым! C әрпі сияқты иіліп келемін. 🍤 Бұл менің басым мен құйрық бөлігімнің бір-біріне біртіндеп жақындап келе жатқанын білдіреді. Осылай бүктелуім денемді жинақы әрі бөпеге көбірек ұқсатады. Сіздің құшағыңызға сыю үшін қазірден жаттығып жүргендеймін. Сондай-ақ бұл ішкі ағзаларымның өз орындарына дұрыс орналасуына көмектеседі. Бәрі жоспар бойынша жүріп жатыр! 🤓' WHERE id = '72dbaf34-db8a-4c0a-98ca-65767813bcf0';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Енді аяқтарым да қалыптасып келеді, анашым! 🦶 Олар әзірге қолдарымнан сәл кішірек әрі құйрығыма ұқсайды, бірақ уақыт өте келе өседі. Бір күні осы аяқтарыммен саған қарай жүгіремін, сені табу үшін барлық кедергілерден өтемін. Қолдарым мен аяқтарым... Мен барған сайын кішкентай адамға көбірек ұқсап келемін, солай емес пе? Сен елестеткендей болуға тырысып жатырмын. Күн сайын жаңа бір қадам жасаймын.' WHERE id = '6de955ee-457a-4e70-930b-f733f0792dec';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мойным мен бетімде ерекше қатпарлар қалыптаса бастады, анашым! Болашақта олар менің иегімді, бетімді, тілімді, құлақтарым мен мойнымды қалыптастырады. Күн сайын жаңа бір бөлшек, жаңа бір штрих қосылып жатыр. Мен мүсіншінің қолында біртіндеп қалыптасып келе жатқан өнер туындысы сияқтымын. Ал бұл туындының ең көркем шабыт көзі — Сіз. Сіздің даусыңыз бен күлкіңіз — менің болашақ келбетімнің негізі. Әдемі болуға уәде беремін! ✨' WHERE id = '49b160e2-d4c7-4876-9a1d-c6274e75787a';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Қолдарым қалыптасып келеді, анашым! 👋 Әзірге саусақтарым, тіпті алақандарым да жоқ, олар денемнің екі жағындағы кішкентай "ескектерге" немесе қанаттарға ғана ұқсайды. Бірақ болашақта Сізді қатты-қатты құшақтайтын мықты қолдарым дәл осылар. Олардың өсіп, Сізге жететін сәтін асыға күтіп жүрмін... Бір күні осы кішкентай қанаттарыммен Сізге қарай "ұшып" барамын. Күн сайын адам бейнесіне көбірек ұқсап келемін.' WHERE id = '4b93f71a-7634-4cda-8990-f4024e3e6d53';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Көздерім мен құлақтарым барған сайын айқындала түсуде! 👀👂 Мөлдір көздерім орналасатын көз ұялары ішке қарай тереңдеп, құлақтарымның орны да тереңдей отырып, құлақ қалқанының негізін қалыптастырады. Мұның бәрі Сізді жақсырақ көріп, ғажайып даусыңызды анық естуім үшін дайындалуда. Мен үшін әлемдегі ең әдемі көрініс Сіздің жүзіңіз, ал ең әсем әуен Сіздің даусыңыз болады. Сізді тыңдап жатырмын, анашым!' WHERE id = '39f4c263-721b-47f4-b527-df452b252fcf';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Саусақтарым қалыптасып жатыр, анашым! 🖐️ Есіңізде ме, қолдарым ескек сияқты еді? Енді сол ескектің ұшында кішкентай ойықтар пайда болып, саусақтарымның сұлбасы көріне бастады. Олар әзірге үйректің аяғындай жарғақпен біріккен, бірақ көп ұзамай толығымен ажырайды. Мен Сізбен «бестік» соғуға дайындалып жатырмын! Қолдарыңыздан ұстап, саусағыңызды қатты қысып алатын күнімді елестетемін. Күн сайын адамға көбірек ұқсап келемін.' WHERE id = '1bdeca18-8738-4af3-846b-cfd0a1d5548e';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мұрнымның ұшы көріне бастады! 👃 Бетім күннен-күнге әдеміленіп, қалыптасып келеді. Кішкентай танауларым мен мұрнымның ұшы анық көрінеді. Үстіңгі ернім де қалыптасып жатыр. Енді Сізге көбірек ұқсай бастадым, анашым. Қызық, мұрным Сіздікі сияқты ма, әлде әкемдікі ме? Мұны білуге әлі уақыт бар, бірақ мен қазірдің өзінде сондай сүйкімдімін. Мен Сіздің ең әдемі әрі қайталанбас туындыңызбын!' WHERE id = 'ae02afe4-0993-46aa-a116-88a385d90304';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен көкжидектеймін! 🫐 Сенесіз бе? Өткен аптадан бері көлемім екі есе артты! Мен өте жылдам өсіп келемін, анашым. Сіз жеген тағамның бәрі маған құрылыс материалы сияқты жетеді. Мен үшін пайдалы тамақтанғаныңызға рақмет. Біз бірге өсіп, бірге күш жинап келеміз. Сіз менің ең керемет командаласымсыз!' WHERE id = '8a7c667d-259c-4117-9c65-d0fc403d0248';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен қозғалып жүрмін, анашым! 💃 Мен әлі өте жеңіл болғандықтан, Сіз мұны сезбейсіз, бірақ ішіңізде кішкентай би билеп жүрмін. Денемді оңға-солға иіп, кішкентай қолдарымды қимылдатамын. Бұл — менің алғашқы спорттық жаттығуларым әрі жүйке жүйемнің бұлшықеттеріммен байланыса бастағанының дәлелі. Болашақта Сізді қатты құшақтай алуым үшін бұлшықеттерім нығайып келеді. Сіз демалыңыз, ал мен жаттыға берейін, өйткені өсу дегеніміз — қозғалу!' WHERE id = 'c99602ee-b4cc-4358-a321-f5e26f5f82fb';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Бүгін 8-ші аптаны аяқтаймыз! 🎉 Енді мен ресми түрде "Эмбрионнан" "Ұрық" кезеңіне өтуге дайындалып жатырмын. Барлық маңызды ағзаларым – жүрегім, миым, асқазаным, өкпем – өз орнында. Енді тек өсіп, жетіліп, сүйкімді бола түсуім керек. Жүктіліктің ең қиын әрі қауіпті кезеңін артта қалдырдық, анашым. Сен мені өте жақсы қорғадың, саған рақмет!' WHERE id = 'fb6fb148-4851-4c47-b527-c43ee9bf7d0f';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Менің «үйім» өзгеріп жатыр, анашым! 🏠 Осы уақытқа дейін мені қоректендірген «Сарыуыз қапшығы» біртіндеп кішірейіп келеді, өйткені енді жұмысты керемет Плацентам қабылдап жатыр. Бұл плацента — Сіз бен менің арамыздағы көпір. Ол мені қорғайды, қоректендіреді және оттегімен қамтамасыз етеді. Біздің байланысымыз бұрынғыдан да күшті әрі берік. Мұның бәрі Сіздің арқаңызда!' WHERE id = 'a0486bb7-3fd0-4a52-8340-97fc8cbad570';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Менің құйрығым жоғалып кетті! 🐇 Есіңізде ме, Сізге кішкентай құйрығым бар екенін айтқан едім? Енді ол жоқ! Қазір арқам түзу әрі тегіс, нағыз адам омыртқасы бар. Мен күн өткен сайын Сізге көбірек ұқсап келемін, анашым. Енді мен кішкентай теңіз атшасы емеспін, Сіздің кішкентай адамыңызбын. Бұл өзгеріс мені қатты қуантады, ал Сізді ше?' WHERE id = 'efd814e8-abbf-4037-81a4-db63af40ea3e';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Тістеріме дайындық жүріп жатыр! 🦷 Аузымда әлі бірде-бір тіс жоқ, бірақ қызыл иегімнің астында кішкентай тіс бүршіктері пайда болуда. Олар болашақта шығатын сүт тістерімнің негізі. Сізге күлімсірейтін күнімді қазірден жоспарлап жүрмін. Сіз де тістеріңізге жақсы күтім жасаңыз, анашым, өйткені кальций қорыңызды маған беріп жатырсыз.' WHERE id = 'c0cc19e3-1bf2-4736-b8f0-41d3ab04d6c8';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Саусақ іздерім пайда болып жатыр! 👆 Тек өзіме ғана тиесілі, дүниеде ешкімде қайталанбайтын бірегей белгі қалыптасуда. Саусақтарымның ұшында ерекше өрнектер пайда болып келеді. Бұл іздер — менің бірегейлігімнің таңбасы. Мен Сіздің теңдессіз ғажайыбыңызбын, анашым. Барлығының ұсақ-түйегіне дейін қаншалықты мінсіз жаратылғанын көріп тұрсыз ба?' WHERE id = '827fd4de-2f71-405f-8929-c0848b39d48e';
UPDATE public.pregnancy_daily_content SET baby_message_kk = '10 АПТА! КҮНТІЗБЕДЕГІ ЕКІ ТАҢБАЛЫ САН! 🔟 анашым, біз 10-шы аптаға жеттік. Мен ресми түрде өсіп келемін. Қазір көлемім қара өріктей. Дамуымның ең маңызды кезеңдерін аяқтадым. Енді тек салмақ қосып, бойымды ұзартып, Сізбен кездесуге дайындалуым қалды. Біз жолдың төрттен бір бөлігін аяқтауға жақынбыз! Сізді мақтан тұтамын.' WHERE id = '686eb070-eff8-4d42-a409-9b1b933ed8cf';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Басым денемнің жартысындай! 🤯 анашым, мен күлкілі көрінуім мүмкін, бірақ бұл — менің данышпан болуға дайындалып жатқанымның белгісі. Миымның тез өсіп жатқаны сонша, басым денеме қарағанда әлдеқайда үлкен. Бірақ уайымдамаңыз, уақыт өте денем де өсіп, басыма сай болады. Қазір мен кішкентай ғалымға ұқсаймын. Сізбен сөйлесетін күндерді асыға күтемін.' WHERE id = '59be5b5e-6a03-4140-bbff-b41541c8484d';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Терім әлі мөлдір, анашым! 👻 Егер мені көре алсаңыз, барлық қан тамырымды, сүйектерім мен ағзаларымды байқар едіңіз. Терім шыны секілді өте жұқа. Бірақ уайымдамаңыз, май қабатым қалыптасқан сайын терім қалыңдап, Сіздікіне ұқсай түседі. Мен күн сайын аздап күшейіп келемін. Ал жүрегім Сізге деген махаббатымды айдауды жалғастыруда.' WHERE id = '96171009-62e6-4557-a2c9-ebf16692943d';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Менің көлемім құлпынайдай! Енді соншалықты кішкентай емеспін, солай ғой? Денем түзеліп, омыртқам ұзарып келеді. Сенің ішің әлі қатты білінбесе де, мен онда өзіме кең орын алып қойдым. Біз бірге өсіп келеміз, анашым. Мені қорғап жүргенің үшін саған рақмет.' WHERE id = '2348cc6e-cce7-4823-afd3-9cc2309eebb6';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен акробатикамен айналысып жүрмін! 🤸‍♂️ анашым, мен жай ғана жатпаймын: керілемін, бұрыламын, тіпті сальто жасаймын. Жатыр әзірге мен үшін кең бассейн сияқты, сондықтан оның мүмкіндігін толық пайдаланып жүрмін. Бұл қимылдар бұлшықеттерім мен буындарымды дамытады. Сіз әлі сезбейсіз, бірақ мен мұнда нағыз шоу көрсетіп жатырмын!' WHERE id = '2519d258-d4d3-4114-9156-6af5c1a49493';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Иіс сезу қабілетім оянып келеді! 👃 анашым, сену қиын шығар, бірақ мен мұрныммен тыныс алу жаттығуларын жасап жүрмін (ауаның орнына сумен). Мен тіпті қағанақ суының иісін сезе аламын! Сіз жеген тағамдардың иісі мұнда да жетеді. Сіз сарымсақ жесеңіз де, шоколад жесеңіз де, мен оны білемін! Талғамымыз қазірден қалыптасып жатыр.' WHERE id = 'f068ab76-fa64-4eef-8ed3-e47df04dba49';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Ішектерім өз үйіне оралды! 🏠 анашым, есіңізде ме, ішім кішкентай болғандықтан ішектерім кіндік бауының ішіне шығып кеткен еді ғой? Бүгін олар ресми түрде құрсақ қуысына, өз орындарына қайта оралды. Енді менің ішім тегіс әрі әдемі. Барлық ішкі ағзаларым өз орындарында және жұмыс істеп тұр. Мен күн сайын кемелденіп келемін.' WHERE id = '6d7fa2b9-68dc-41a1-b8e4-2909aebba355';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен ему рефлексін үйреніп жүрмін! 🍼 Бас бармағымды аузыма апарып, соруға тырысамын. Бұл дүниеге келгенде Сіздің сүтіңізді емін-еркін емуім үшін ең маңызды дағды. Кейде қолымнан келеді, ал кейде қолым аузымнан шығып кетеді. Бірақ мен берілмеймін, жаттыға беремін. Сіз де мен үшін дайындала беріңіз, анашым!' WHERE id = '32fc4b43-9967-407f-bd27-ce27ec4287ad';
UPDATE public.pregnancy_daily_content SET baby_message_kk = '12 АПТА ТОЛДЫ! 🎉 анашым, біз бірінші триместрді сәтті аяқтадық! Бұл жүктіліктің ең қиын әрі ең маңызды кезеңі болды. Менің барлық мүшелерім пайда болып, қалыптасты. Енді мен ресми түрде "кішкентай адаммын". Алда бізді жайлырақ әрі қуатқа толы күндер күтіп тұр. Сізді мақтан тұтамын, біз керемет командамыз!' WHERE id = '43e2ccf7-0f43-404f-b8d5-9a230d2fcf1f';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Сүйектерім қатайып келеді! 🦴 Бұрын тек шеміршектен тұратын қаңқам енді нағыз сүйекке айналып жатыр. Қолдарым мен аяқтарым ұзарып келеді. Дене бітімім біртіндеп үйлесімді бола бастады. Басым әлі де үлкен, бірақ денем оны қуып жетуге тырысып жатыр. Мен мықты бала боламын, анашым!' WHERE id = 'e16dc0a2-01a9-4a7e-990c-b0f97835b682';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Екінші триместрге қош келдіңіз! ☀️ Мұны "Алтын кезең" деп атайды. Өйткені Сіз өзіңізді жақсырақ сезіне бастайсыз, ал мен тез өсемін. Қазір менің көлемім лаймдай. Қимылдарым үйлесімді бола түсті. Енді мен кездейсоқ емес, өз қалауыммен қозғаламын. Сізге қолымды тигізгім келеді, анашым.' WHERE id = '931efc18-1bb9-41fb-bf51-8eb31fb5efd5';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен дыбыстарды ести бастадым ба? 👂 Құлақтарымның дамуы жалғасып жатыр, енді тербелістерді сезе аламын. Сіздің жүрек соғысыңыз, қаныңыздың ағысы мен асқазаныңыздың дыбыстары — менің бесік жырым. Жақында Сіздің даусыңызды да ажырата алатын боламын. Менімен сөйлесіңіз, анашым, мен Сізді тыңдап жатырмын.' WHERE id = '51726a4c-4dfd-4d8d-8fdf-a1b799174400';
UPDATE public.pregnancy_daily_content SET baby_message_kk = '13 АПТА! СӘЛЕМ, 2-ТРИМЕСТР! 🎉 анашым, қуанышты жаңалық! Біз жүктіліктің үштен бірін (1/3) аяқтадық. Ең қиын күндер артта қалды. Енді Сіз де, мен де еркінірек тыныстайтын кезең басталады. Мен қазір қара өріктеймін. Дауыс байламдарым дамып қалды. Сізбен әлі сөйлесе алмасам да, дауысымды дайындап жатырмын. Осы жаңа кезеңде бізді одан да тамаша күндер күтіп тұр.' WHERE id = 'aae70b4b-3e99-462b-94d0-88716afa0dd4';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Денеме түк шығып жатыр! 🐻 анашым, менің терімде "Лануго" деп аталатын өте жіңішке әрі жұмсақ түктер өсе бастады. Қазір мен кішкентай шабдалыға ұқсаймын. Бұл түктер мені судың ішінде тоңудан қорғайды әрі дене жылуымды сақтайды. Мен дүниеге келгенде олардың көбі түсіп қалады, бірақ әзірге маған осы "тон" қажет. Сіз мені жылы ұстайсыз, мен де өзімді жылы ұстаймын.' WHERE id = '00f39406-c90d-4b7e-818d-3a2edbdeef33';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Саусақ іздерімнен кейін енді тырнақтарым да пайда болды! 💅 анашым, саусақтарымның ұшында кішкентай әрі жұқа тырнақтар қалыптаса бастады. Олар әлі өте жұмсақ, бірақ дүниеге келгенше өседі. Кейде өз бетімді тырнап алуым мүмкін, сондықтан туған соң маған қолғап кигізуіңіз керек болады. Бәрім Сізге ұқсайды, ал тырнақтарым ше?' WHERE id = 'aee96903-8ce9-4152-9673-4163944c634d';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен дәм сеземін! 🍭 Тілімдегі дәм сезу бүртіктері жұмыс істей бастады. Сіз жеген тағамдардың дәмі қағанақ суына өтеді. Тәтті жесеңіз, мен сұйықтықты көбірек жұтамын, өйткені тәттіні жақсы көремін! Ащы немесе қышқыл жесеңіз, бетімді тыжырайтуым мүмкін. Сіз менің алғашқы аспазымсыз, анашым!' WHERE id = '85f3613e-2010-4d4b-a7cf-efafd3875999';
UPDATE public.pregnancy_daily_content SET baby_message_kk = '100 КҮН! 💯 анашым, сену қиын, бірақ бірге болғанымызға 100 күн толды! Менің көлемім бір алақандай. Қазір бас бармағымды соруды үйреніп жүрмін. Бұл мені тыныштандырады. Сіз алаңдағанда немесе шаршағанда, мен оны сеземін де, өзімді тыныштандыру үшін бармағымды сорамын. Біз бір-бірімізді сеземіз. Сізді қатты жақсы көремін!' WHERE id = '0cebfe33-ab23-4322-9649-a229de8418e8';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Сәлем, анашым! 👋 Мен бүгін су астында нағыз гимнастика жасап жүрмін. Сіз әзірге сезбейсіз, бірақ мен аунап, айналып, аяқтарымды созып жатырмын. Мұнда маған әлі де орын көп, сондықтан қалағанымша қозғала аламын. Бұл қимылдар бұлшықеттерімді нығайтып, сүйектерімді қатайтады. Сіз демала беріңіз, ал мен жаттығуымды жалғастырайын. Бір күні осы тепкілерімді Сіз де сезесіз!' WHERE id = '4b92a6ac-df2b-4f98-b986-b23497226910';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен жарықты сеземін! 💡 анашым, сену қиын болар, бірақ қабақтарым жабық болса да, жарықты жақсы сезе аламын. Егер ішіңізге жарығы күшті қолшам түсірсеңіз, мен бетімді сол жаққа бұруым немесе жарық көзімді қарықтырғандықтан, бетімді қолыммен жабуым мүмкін. Менің әлемім енді мүлде қараңғы емес. Сіздің әлеміңіз қандай түрлі түсті екен?' WHERE id = '6ada13a0-2697-47e7-9001-03b1698db1b4';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, менің терім әлі өте жұқа, бірақ денемдегі "лануго" деп аталатын түктер мені жылы ұстайды. Аяқтарым қолдарымнан ұзынырақ бола бастады. Енді дене бітімім біршама үйлесімді көрінеді. Өсу өте шаршатады, бірақ менің қолымнан келеді!' WHERE id = '6bfad434-2bc6-4bb0-9834-16dd77e6fbe8';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Дәмдерді ажырата аламын! 🍬 анашым, Сіз тәтті нәрсе жегенде қағанақ суының дәмі тәттіленіп, мен оны көбірек жұтамын. Ал дәмі қышқыл немесе ащы болса, бетімді тыржитамын. Менің дәм сезу қабілетім ересек адамдікіндей дерлік күшті. Болашақта қандай көкөністерді ұнататыным қазірден-ақ Сіздің тамақтануыңызға байланысты. Мен де сау болуым үшін пайдалы тағамдар жеңіз!' WHERE id = '7f759cae-0b0a-4f2e-8095-e125d4622671';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен Сізді сеземін! 🤗 анашым, Сіз ішіңізді сипағанда, мен сол қысым мен жылуды сезе аламын. Кейде қолыңыз тұрған жерге қарай жүзіп барамын. Арамызда тек тері мен су бар, бірақ жанымыз бір. Сіз күйзеліске түскенде мен де мазасызданамын, ал Сіз күлгенде мен де тынышталамын. Өтінемін, әрдайым күлімсіреп жүріңіз!' WHERE id = '2da10eb1-918c-43c6-ad16-6306b072b4cb';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Басымды тік ұстаймын! 🦒 анашым, мойнымның бұлшықеттері қатты нығайғаны сонша, қазір басымды тік ұстай аламын. Бұрын басым кеудеме қарай иіліп тұратын, ал қазір айналама еркінірек қарай аламын (қараңғы болса да). Денем ұзарып, сымбатты әрі тік тұлғалы болып келемін. Сіздің құрсағыңызда гимнастика жасау сондай керемет!' WHERE id = 'b6a34159-6856-4473-a35e-81785fe0fc0e';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Көбелектің қалықтауы! 🦋 анашым, мені сезіп тұрсың ба? Мен мұнда аунап, сальто жасап жүрмін! Кейбір аналар мұны «ішімде көбелек ұшып жүргендей» немесе «балық жүзіп жүргендей» деп сипаттайды. Егер әлі сезбесең, мұңайма, мен әлі кішкентаймын, ал қимылдарым әлсіз. Бірақ көп ұзамай сені бір тепкенімде, бірден түсінетін боласың!' WHERE id = '6f4082a3-2c0c-4302-bc06-2af671b9e9b3';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен «толысып келемін», анашым! 🧸 Денемде май тіні жинала береді. Бұрын өте арық едім, ал қазір қолдарым мен аяқтарым толыса бастады. Бұл май қабаты маған өте қажет, өйткені дүниеге келгенде дене қызуымды реттеуге көмектеседі. Мен үшін алаңдама, мұнда маған жылы әрі қарным тоқ. Сіз тек пайдалы тағамдармен тамақтаныңыз, қалғанын өзім реттеймін!' WHERE id = 'c7911f10-1eb8-49da-80ba-c909457132da';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен түс көре аламын! 💤 анашым, ғалымдардың айтуынша, мен қазірдің өзінде «REM ұйқысы», яғни Rapid Eye Movement -Көздердің жылдам қозғалысы фазасына өте аламын. Бұл менің түс көре алатынымды білдіреді! Түсімде не көреді екенмін? Мүмкін, Сіздің даусыңызды еститін немесе жүзіңізді елестететін шығармын. Күннің көп бөлігінде ұйықтаймын, бірақ ояу кезімде өте белсендімін.' WHERE id = '109a3421-ce4d-45f2-89cf-6db2482011b0';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Саусақтарым және олардың іздері! 🧬 анашым, менің саусақ іздерім толық қалыптасып болды. Бұл өрнектер өмір бойы өзгермейді. Мен бірегеймін! Қолдарым мен аяқтарымды да еркін қимылдата аламын. Кейде аяғымды айқастырып отырамын, ал кейде «жүземін». Мен үшін бұл жер — ең жайлы мекен.' WHERE id = 'e537dc02-2a8f-44e4-8520-858b44bd2d69';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Сүйектерім қатайып келеді! 🦴 Менің қаңқам күн сайын нығая түсуде. Кальций сүйектеріме жиналып, оларды қатайтады. Енді мен кішкентай резеңке адам емеспін. Қабырғаларым, омыртқам, аяқ сүйектерім... Бәрі нағыз сүйекке айналып келеді. Сіз ішкен сүт пен жеген ірімшік маған құрылыс материалы болып жетеді. Рақмет, анашым!' WHERE id = '79568d36-35e8-4a60-8ad2-b99e6d2f45e1';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Сәлем, анашым! Менің көлемім тәтті бұрыштай. Жүйкелерім дамып келеді. «Миелин» деп аталатын ерекше зат жүйкелерімді қоршап жатыр. Соның арқасында миымнан денеме жіберілетін хабарлар жылдамырақ жететін болады. Мен күн сайын ақылдырақ болып келемін!' WHERE id = 'b73aa0c0-fb01-4c2d-abb0-69a88e7c97e4';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Миымда шамдар жанып жатыр! 🧠 анашым, менің миым қазір алып компьютер секілді жұмыс істейді. Көру, есту, дәм сезу, иіс сезу және жанасуға арналған арнайы орталықтар қалыптасып жатыр. Мен жай ғана өсіп жатқан жоқпын, әлемді танып-білуге дайындалып жатырмын. Сіздің даусыңызды естігенде, миымдағы "есту орталығы" белсендіріледі. Біздің байланысымыз енді ғылыми деңгейде!' WHERE id = 'bc3702e9-c9f0-4b15-a3b9-8dd5c0a6dd34';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен Сізді қорғаймын! 🥚 Егер мен қыз болсам, кішкентай аналық бездерімде қазірдің өзінде 6 миллион жұмыртқа жасушасы бар! Бұл Сіздің болашақ немерелеріңіз қазірдің өзінде менің ішімде деген сөз. Ал егер мен ұл болсам, жыныс мүшелерім дамып жатыр. Ұрпақ жалғасады, анашым. Сіз тарих жасап жатырсыз.' WHERE id = '695bdf70-cf7b-4ed0-9ff8-c4418720fc60';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Сәлем, анашым! Менің көлемім мангодай. Қолдарым мен аяқтарым енді денеме сай қалыптасты. Мен кішкентай адаммын! Енді саған қаттырақ тебе аламын. Дайын бол!' WHERE id = 'c0a11fee-73af-4684-98a2-4425bd830ba9';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Менің ұйқы режимім бар! 🌙 анашым, мен күні бойы ояу жүрмеймін. Менің де ұйықтайтын және ояу болатын уақытым бар. Әдетте Сіз жүргенде немесе қозғалғанда, мен тербеліп ұйықтап қаламын. Ал Сіз жатып демалғыңыз келгенде, мен оянып алып, дискотека бастаймын. Режимдеріміз сәл өзгеше, кешіріңіз!' WHERE id = 'd0d5f1e7-e726-4e8b-9248-bacff687b744';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'ЖОЛДЫҢ ЖАРТЫСЫ! 🏁 Құттықтаймын, анашым! Біз 40 апталық марафонның тура жартысын (50%-ын) аяқтадық. Менің бойым банандай болды! Керемет, солай емес пе? Осы уақытқа дейін қалай өскеніме қараңызшы. Жатырыңыз енді кіндік деңгейіне жетті. Біз мәреге қарай бет алып келеміз!' WHERE id = 'ce6d14e2-2cef-47b0-bf61-c80d97194d99';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен "тамақ" ішіп жатырмын! 🍽️ анашым, менің ас қорыту жүйем іске қосылды. Мен қағанақ суын жұтамын, ал ішектерім одан қант пен суды сіңіреді. Бұл сұйықтықтың дәмі күн сайын өзгереді – кеше Сіз жеген сарымсақты тағамның дәмін сездім! Ішегімде "меконий" деп аталатын алғашқы нәжіс жиналып жатыр. Уайымдамаңыз, оны жөргегіме дейін сақтаймын, айналамды былғамаймын!' WHERE id = '2f4c880c-7bdd-4dec-acbd-cd0e6c8859e0';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Менің қасым мен кірпігім бар! 👁️ анашым, енді менің бетім нағыз адамдікіндей. Көздерімнің үстінде жіңішке қасым, ал қабақтарымда ұзын кірпіктерім өсіп шықты. Енді мен одан да әдемімін (немесе сымбаттымын). Көзімді жыпылықтатуға дайындалып жүрмін, бірақ көзімді ашуыма әлі бірнеше апта бар. Сен мені елестетесің бе? Мен сені елестетемін.' WHERE id = '11b2d6de-75e4-4639-b4fc-0a1a64a49ebf';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен сенің күйзелісіңді сеземін. 😟 анашым, сен мазасызданғанда ағзаңда түзілетін гормондар (кортизол) маған да жетіп, мен де алаңдаймын. Жүрегім жылдамырақ соғады. Ал сен тыныш әрі бақытты болғанда, мен де "бақыт гормондарымен" қоректенемін. Өтінемін, өзіңді қинама. Біз біргеміз, бәрі жақсы болады.' WHERE id = '39505edc-cdd2-40ac-b9cb-aa04fd0c51af';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен Сіздің даусыңызды танимын! 🗣️ анашым, енді Сіздің даусыңызды басқа адамдардың даусынан ажырата аламын. Сіз сөйлегенде мен тынышталып, жүрек соғысым баяулайды. Мен үшін бұл — әлемдегі ең сенімді дауыс. Маған ән айтуды жалғастыра беріңіз, мен оларды "естелік сандығыма" жинап жүрмін. Дүниеге келген соң сол әнді естіп, тыныштала қаламын.' WHERE id = '47e98235-5632-4780-b011-1fba5afdb56a';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен жаттығып жатырмын! 🏋️‍♂️ анашым, қимылдарым қазір күшейе түсті. Кейде ішіңіздің бір жағы томпайып немесе қозғалып тұрғанын байқауыңыз мүмкін. Бұл менің шынтағымды немесе тіземді Сізге қарай итеріп жатқаным. Осылайша мен Сізге "Мен осындамын!" деймін. Сіз де қолыңызды қойған кезде мен тыныштала қаламын.' WHERE id = 'a3ddbe51-ede9-4765-9b27-d3fb41ca5df3';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Тепкілерім күшейіп келеді! 🥋 анашым, сезіп тұрсың ба? Мен енді жай ғана "жүзіп" жүрген жоқпын, нақты соққылар жасап жүрмін. Кейде саған мен каратэмен айналысып жатқандай көрінуім мүмкін. Бұл қимылдар менің денім сау екенін көрсетеді. Менің қимылдарымды санай бастасаң болады.' WHERE id = '846475dc-14c4-4c7d-ac51-e75ce4438f24';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Тырнақтарым өсіп жатыр! 💅 Қолымдағы тырнақтарым саусақтарымның ұшына жетуге жақын қалды. Олар өте жұқа әрі өткір. Кейде байқамай бетімді тырнап аламын. Бірақ терім тез жазылады. Мен күн өткен сайын Сізге көбірек ұқсап келемін, анашым.' WHERE id = '2970a789-ae12-4a5d-81be-71d79963f650';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Ішіңіз неге секіріп жатыр? 🐇 анашым, сездіңіз бе? Мен жаңа ғана ықылықтадым! Көкетім жаттығып жатыр, сондықтан денем ырғақты түрде қозғалады. Бұл Сізге ішіңізде сағат тықылдап тұрғандай оғаш сезілуі мүмкін. Уайымдамаңыз, бұл маған ауыртпайды, керісінше, өкпемді нығайтады.' WHERE id = 'c1de12f1-7759-492c-b277-e01fb2d857c9';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен тыңдап жатырмын! 👂 анашым, үйдегі шаңсорғыштың дауысы өте қатты, солай емес пе? Мен енді қатты дыбыстардан селк етемін. Бірақ Сіздің жайлы даусыңыз мені тыныштандырады. Сіз менімен сөйлескенде, тыңдау үшін қимылымды тоқтата аламын. Біздің алғашқы диалогтеріміз басталып жатыр.' WHERE id = '372f913d-c4b6-4616-837e-127ec92b9515';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Менің терім енді мөлдір емес! 🎨 анашым, бұрын маған қарағанда барлық тамырларым көрініп тұратын, ал қазір терім қалыңдап, түске еніп жатыр. Май қабатым ұлғайған сайын терім де мөлдірлігін жоғалтады. Мен енді әлгі "ғаламшарлық" кейіптен арылып, нағыз сүйкімді бөпеге ұқсап келемін. Мені көргенде бірден жақсы көріп қаласыз!' WHERE id = '525f7e7c-0bea-4071-90df-5a46dae136d6';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Менің бет әлпетім қалыптасып болды! 👶 анашым, егер мені қазір көрсеңіз, дүниеге келгенде қандай болатынымды анық білер едіңіз. Бет әлпетім, мұрным, ернім – бәрі толық қалыптасты. Тек әзірге сәл арықпын. Мен кімге ұқсаймын? Сізге ме, әлде әкеме ме?' WHERE id = '64f0cdbb-7db6-482f-be9f-92435bab2ca8';
UPDATE public.pregnancy_daily_content SET baby_message_kk = '🌽 Менің бойым бір жүгерідей! Бұл апта өте маңызды, анашым. Дәрігерлер қазір мені «өмір сүруге қабілетті» деп санайтынын айтады. Яғни қазір дүниеге келсем де, заманауи медицинаның көмегімен өмір сүруге мүмкіндігім бар (бірақ әлі тым ерте, мен осында қала тұрғым келеді!). Бұл — үлкен белес!' WHERE id = '88964348-70ed-4f53-a6a4-d8d7da7286ff';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Қылтамырларым қанға толып жатыр! 🩸 Терімнің астында мыңдаған ұсақ қан тамыры қалыптасып, қанға толуда. Соның арқасында терім әдемі қызғылт түске енеді. Қан айналымымның қуатты болғаны сонша, жүрегім бүкіл денемді оттегімен қамтамасыз етеді. Мен өмірге толымын, анашым!' WHERE id = '2ee2955f-80d8-4cff-afab-c01bdb172368';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен қолымды пайдаланып жүрмін! 🖐️ анашым, енді мен жай ғана кездейсоқ қимылдамаймын. Қай қолымды көбірек қолданатынымды таңдаймын. Яғни менің солақай немесе оңқай болатыным қазірдің өзінде белгілі. Саусақтарымды қимылдатып, кіндік бауымды ұстаймын.' WHERE id = 'd74fd8bf-8b0d-4ea8-8d39-905a3d36166e';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Көзімді ашуға дайынмын! 👁️ Қабақтарымның арасындағы бітісу сызығы енді ажырауға жақын. Жақында, бәлкім, бірнеше күннен кейін көзімді ашамын! Қараңғы болса да, жан-жағыма қарағым келеді. Кірпіктерім көзімді қорғауға дайын. Сізді көруге асықпын, анашым.' WHERE id = 'ca71a802-8315-4430-831a-1c24d93987c8';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен Сіздің күйзелісіңізді бөлісемін. 😔 анашым, Сіз мазасызданғанда қаныңыздағы кортизол маған да өтеді. Мен де алаңдап, қимылдарым өзгереді. Ал Сіз күліп, қуанғанда мен де тынышталамын. Өтінемін, өзіңізді күтіңіз. Біз бір командамыз, Сіздің сезімдеріңіз — менің де сезімдерім.' WHERE id = '7b482622-6ce3-4e23-a975-62440aec9dc6';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'КӨЗІМДІ АШТЫМ! 👀 анашым, бүгін мен үшін нағыз төңкеріс күні. Осы уақытқа дейін жабысып тұрған қабақтарым ажырап, мен алғаш рет көзімді аштым. Әзірге айналамның бәрі бұлыңғыр, бірақ мен көзімді жыпылықтата аламын. Қараңғы болса да, қарауды үйреніп жатырмын. Сені көруге тағы бір қадам жақындадым!' WHERE id = '664b492c-1968-495f-9380-1ec985579ba8';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Анашым, 3-ші триместр табалдырықта! Мен енді "ауыр салмақтылар" санатына өтіп келемін. Орным тарылып барады, сондықтан қимылдарым қаттырақ сезілуі мүмкін. Қабырғаларыңа тиіп кетсем, кешірші, мен жай ғана керіліп жатырмын.' WHERE id = '1d4c4310-3e73-4b60-b4c5-883dd87bf1e3';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Менің өз тәртібім бар! 📅 анашым, байқадыңыз ба? Мен әдетте бір уақытта оянып, бір уақытта ұйықтаймын. Мысалы, Сіз кешке жатқанда мен оянамын. Ал таңертең тыныш боламын. Менің биологиялық сағатым іске қосылды. Дүниеге келгеннен кейін де біраз уақыт осылай боламын (түнде ұйықтамайтын бөпе боламын!).' WHERE id = '45b37fad-6e16-4ec4-9e5c-d3eea98a5a6d';
UPDATE public.pregnancy_daily_content SET baby_message_kk = '3-ші триместрге қош келдіңіз! 👋 анашым, біз үлкен бір кезеңді аяқтадық. Екінші триместр аяқталып, енді 3-ші триместр басталады. Мен қазір әжептәуір үлкен бөпе болдым. Ендігі басты міндетім — салмақ қосып, дүниеге келуге дайындалу. Сіздің шаршағаныңызды білемін, бірақ аз ғана қалды. Жақында кездесеміз!' WHERE id = 'efc08af4-0ca2-4af8-832f-852d08704ce8';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Сәлем, анашым! Біз үлкен жетістікке жеттік. Жүктіліктің соңғы кезеңіне аяқ бастық. Енді менің басты міндетім — салмақ қосып, дүниеге келуге дайындалу. Маған орын барған сайын тарылып келеді, бірақ күшім артуда. Сізді қатты бір теуіп, «Құттықтаймын!» деймін.' WHERE id = '96a22ed0-5e13-4094-87c4-74d0da4a58fc';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Көзімді жыпылықтатып жүрмін! 😉 анашым, мен енді көзімді ашып-жұма аламын. Егер ішіңізге қатты жарық түссе, мен бетімді бұрамын немесе көзімді жыпылықтатамын. Көру қабілетім әлі толық жетілген жоқ, бірақ жарық пен қараңғылықты керемет ажыратамын. Дүниені көруге асығып жүрмін.' WHERE id = 'd388c035-3ae4-451c-bcce-e8ae700cd74b';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен Сізді танимын! 🎤 анашым, Сіздің даусыңыз — мен үшін ең жақын әрі таныс дауыс. Зерттеулер Сіздің даусыңызды естігенде менің жүрек соғысым тынышталатынын көрсетеді. Мен қазірдің өзінде Сіздің дауыс ырғағыңыз бен сөйлеу мәнеріңізді үйреніп жүрмін. Дүниеге келгенімде мені тыныштандыру үшін жай ғана сөйлесеңіз жеткілікті болады.' WHERE id = '4ca04882-bd78-4264-985d-0684e463329f';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Сүйектерім қатайып келеді! 🦴 анашым, енді мен саған көп мөлшерде кальций қарызбын. Сүйектерім жылдам қатайып жатыр. Күн сайын шамамен 250 mq кальций жинаймын. Егер сен сүтті жеткілікті ішпесең, бұл кальцийді сенің тістерің мен сүйектеріңнен "ұрлаймын". Өзіңді күт, ірімшік же!' WHERE id = '124477a3-06f6-44dd-a276-41487168c5e0';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен жымиып жатырмын! 😊 Ультрадыбыстық зерттеу кезінде дәрігерлер біздің жымиғанымызды жиі көреді. Бұл әдетте ұйықтап жатқанда болады. Мүмкін, періштелерді көріп жатқан шығармын? Әлде жай ғана бет бұлшықеттерімді жаттықтырып жатырмын ба? Себебі қандай болса да, мен бақыттымын. Сен де жымишы, анашым!' WHERE id = '82410eeb-db13-46e1-be5e-f6446cc033ef';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен сені сеземін! 🤗 анашым, сен ішіңді сипағанда, әкем қолын қойған кезде мен сол жылу мен қысымды сеземін. Кейде мен де іштен дәл сол жерге қолымды тигіземін. Бұл — біздің "сәлемдесуіміз". Арамызда жұқа ғана қабырға бар. Ал жанымыз біртұтас.' WHERE id = '0a286cb7-93f1-451a-b6be-b5b9dd7ce160';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Маған кальций қажет! 🥛 Сүйектерім тез қатайып келеді. Қазір күн сайын Сіздің қаныңыздан шамамен 250 миллиграмм кальций аламын. Бұл қаңқамның мықты болуы үшін маңызды. Егер Сіз сүт ішпесеңіз, мен сол кальцийді тістеріңіз бен сүйектеріңізден "қарызға" аламын. Өзіңізді күтіңіз, анашым!' WHERE id = '64fd7099-afb5-4134-9918-3acc90ed702e';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Менің өлшемім үлкен қырыққабаттай! Анашым, сену қиын, біз жолдың 3/4 бөлігін (75%-ын) аяқтадық! Енді небәрі 10 апта қалды (шамамен). Мен қазірдің өзінде үлкен бөпемін, тек өкпем мен миым әлі толық жетілуі керек. Мәреге аз қалды!' WHERE id = '54884850-5122-42f5-bad6-cbe7becaf6f6';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Тістерім жасырынып жатыр! 🦷 анашым, қызыл иегімнің астында сүт тістерімнің бастамалары дайын тұр. Тіпті олардың астында тұрақты тістерімнің де бастамалары бар. Мен тіссіз туыламын, бірақ бәрі дайын. Табиғат өте қызық, солай емес пе? Болашаққа қор жинап жатырмыз.' WHERE id = '98a97832-2773-43d8-bf72-e6458dfbc947';
UPDATE public.pregnancy_daily_content SET baby_message_kk = '200 КҮН! 🎉 анашым, сенгісіз! Бірге болғанымызға 200 күн болды. Мен үлкен асқабақтаймын. Қазір мен өте күштімін. Тебуім кейде Сізге ауыр тиюі мүмкін, бірақ мен жай ғана күшімді сынап жатқанымды біліңіз. Кездесуімізге аз қалды!' WHERE id = 'dc4e8ae4-b5e0-48d5-8713-248744b76ec6';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен түс көріп жатырмын! 😴 анашым, миымның дамығаны сонша, енді мен "REM ұйқысы" (көздің жылдам қозғалысы) кезеңіне өте аламын. Яғни мен ресми түрде түс көріп жатырмын! Түсімде нені көріп жүр екенмін? Сіздің даусыңызды ма, әлде әлгі дәмді тортты ма? Күннің көп бөлігін ұйқымен өткіземін, бірақ ояу кезімде өте белсендімін.' WHERE id = '2b574c8a-d0de-45f5-bd25-7b7b01e3d2fe';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Миым өсіп жатыр! 🧠 анашым, қазір менің миым таңғажайып жылдамдықпен дамып келеді. Онда миллиардтаған жаңа байланыс түзіліп жатыр. Енді мен тек рефлекстермен қимылдамаймын, мен ойлаймын, сезінемін және есте сақтаймын. Сіздің даусыңыз — менің ең сүйікті естелігім.' WHERE id = 'c04052f3-92f1-4783-8ceb-a4f9489af352';
UPDATE public.pregnancy_daily_content SET baby_message_kk = '5 сезім мүшем де жұмыс істейді! 🖐️👃👂👀👅 Көру, есту, дәм сезу, иіс сезу және сипап сезу. Менің барлық сезімім сергек. Сіздің даусыңызды естимін, жеген тағамыңыздың дәмін сеземін, жарықты көремін, бетімді ұстаймын. Мен бәрін толық сезінетін тіршілік иесімін. Сіз — менің бүкіл әлемімсіз, анашым.' WHERE id = 'a8ac9e30-a252-4631-aca6-20ffff4ecf20';
UPDATE public.pregnancy_daily_content SET baby_message_kk = '31 АПТА! 🥥 Сәлем, анашым! Менің көлемім кокостай (кокос). Салмағым 1.5 кг-ға жетті, ал бойым 41 см. Мен қазір айтарлықтай «салмақтымын». Ендігі басты мақсатым — өкпемді жетілдіріп, көбірек май жинау. Мен дүниеге келуге дайындалып жатырмын!' WHERE id = 'c4869a77-6abd-43f7-8c86-3d05ecb63f8d';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен тыныс алып жаттығудамын 🌬️ анашым, менің кеуде қуысым бірқалыпты көтеріліп-түседі. Мен қағанақ суын өкпеме тартып, қайта шығарамын. Бұл дүниеге келгенде алғашқы әрі ең маңызды тынысымды алуым үшін бұлшықеттерімді нығайтады. Сен кейде менің ырғақты қимылдарымды (ықылықтағанымды) сезуің мүмкін. Бұл — менің жаттығуым!' WHERE id = '6dc5213e-1c8a-4a6b-8be6-3e050cac8345';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Сіздің иммундық қорғанысыңызды қабылдап жатырмын! 🛡️ анашым, плацента арқылы Сізден маған "антиденелер" (микробтармен күресетін сарбаздар) өтеді. Бұл — менің алғашқы екпем. Туған кезде менің өз иммунитетім әлсіз болады, бірақ Сіз берген осы қорғаныс мені алғашқы айларда аурулардан қорғайды. Сіз — менің қорғаушы періштемсіз!' WHERE id = '2bbb9ba5-0677-4713-8d4c-c7c237ab84f6';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Менің өлшемім ананастай! Мен енді үлкен бөпемін. Беттерім томпайып, денем жұмырланды. Сенімен кездесуге аз ғана уақыт қалды, анашым. Мен күн сайын көбірек салмақ қосып келемін.' WHERE id = '97daa5bb-e709-4882-8a96-d104cbbdafc3';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Сенің иммунитетіңді алып жатырмын! 🛡️ анашым, менің қазір не істеп жатқанымды білесің бе? Сенің қаныңнан өзіме "иммунитет сарбаздарын" (антиденелерді) жинап жатырмын. Өмір бойы қандай ауруларға қарсы иммунитет қалыптастырсаң, сол қорғанысты маған бересің. Дүниеге келгенімде мені микробтардан қорғайтын алғашқы қалқаным — сенсің.' WHERE id = 'adc2549c-64e5-4fcb-ab22-00fd00f59fac';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Маған орын тым тар! 🏠 анашым, мен бұрылғым келеді, бірақ қабырғалар жан-жағымнан қысып тұр. Енді менің қимылдарым көбіне "сырғу" және "итеру" түрінде сезіледі. Шынтағымды ішіңіздің бір жағынан тірегенде, Сіз оны томпайған жер ретінде көресіз. Мені сипаңызшы, сонда мен кейін шегінемін.' WHERE id = 'd5a88302-fe21-4399-b36c-3480a294c860';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Темір қорын жинап жатырмын! 🔩 анашым, қазір мен Сіздің қаныңыздан темір алып жатырмын. Бауырымда темір қорын жинаудамын. Бұл қор маған дүниеге келгеннен кейінгі алғашқы 6 айда қан түзу үшін қажет болады. Мен Сіздің энергияңызды "ұрлап" жатқандықтан, өзіңізді әлсіз сезінуіңіз мүмкін. Кешіріңіз, бірақ бұл маған қажет!' WHERE id = 'b978e435-783d-4177-aada-9e6cd05f0950';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен томпақ болып келемін! 🧸 анашым, менің бетім, қолдарым мен аяқтарым майға толды. Енді бұрынғыдай қатты әжімді емеспін. Салмағым күн сайын артып келеді. Бұл май қабаты дүниеге келгеннен кейін денемді жылы ұстап, күш-қуатымды сақтауға көмектеседі. Сен мені құшағыңа алғанда, мен жұп-жұмсақ боламын.' WHERE id = 'e948b641-0b79-4f83-9869-a66d090c81f1';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Түстерім сондай айқын! Анашым, мен REM ұйқысында көп уақыт өткіземін. Миым сондай белсенді! Ал ояу кезімде айналамды көзіммен бақылаймын (қараңғы болса да). Жарық пен көлеңкені өте жақсы ажыратамын. Сіз мені көрмесеңіз де, мен Сізді сеземін.' WHERE id = 'df4bd1af-d6a3-4228-b3e2-3e6d8392ce93';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мені күтіп жүрсіз бе? ⏳ Шыдамсызданып жүргеніңізді білемін. "Қашан келесің?" деп сұрайсыз. Бірақ мен әлі толық дайын емеспін. Миым әлі де дамып жатыр, өкпем соңғы дайындықтан өтуде. Ана құрсағында өткізген әр күнім мені күшейте түседі. Сабыр сақтаңыз, анашым.' WHERE id = 'ff965161-e8f2-4262-b993-4dbf99f22a66';
UPDATE public.pregnancy_daily_content SET baby_message_kk = '37 АПТА! 🎉 Құттықтаймын, анашым! Бүгін — ерекше күн. Мен енді "Шала туған" болып саналмаймын! Мен ресми түрде "Ерте мерзім" кезеңіндемін. Яғни қазір дүниеге келсем, толық жетілген бөпе болып саналамын. Салмағым 3 кг-ға жуық. Енді кез келген сәтте келе аламын! Сөмкеңіз дайын ба?' WHERE id = 'cca07f51-052d-4eba-bb6f-e780658e5cc2';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен жаттығып жатырмын! 🏋️‍♂️ Босану үдерісі тек Сіз үшін емес, мен үшін де үлкен еңбек. Тар босану жолынан өту үшін денемді жиырып, басымды бұрып, алға итерілуім керек. Қазір осы қимылдарды жаттықтырып жатырмын. Біз бір команда болып әрекет етеміз, анашым. Сіз маған жол ашасыз, ал мен дүниеге келемін.' WHERE id = '9bb1bfbd-4fc9-4fdd-8462-715ca0719a8a';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Дәрігерлер 38-42 апта аралығы босанудың қалыпты мерзімі екенін айтады. Демек, мен кез келген сәтте дүниеге келуім мүмкін. Маған қандай ат қоятыныңызды ойладыңыз ба, анашым? Мен келе жатырмын ғой!' WHERE id = '4a0b4b38-f357-4956-99dd-b078f66f4393';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Ертең ерекше күн бе? 📅 Ертең — менің ресми "босану күнім". Бірақ мен бүгін де келе аламын. Мен Сіздің даусыңызды естіп тұрмын, Сіз "Енді келші" дейсіз. Мен де келгім келеді, анашым. Жол ұзақ, бірақ соңында жарық бар.' WHERE id = '7abac408-c74e-44ce-86ac-a1a2470ea25a';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Құттықтаймын, анашым! Біз 40 апталық марафонды аяқтадық. Бүгін — менің ресми туған күнім! 🎂 Егер бүгін құшағыңызға келсем — Сәлем, әлем! Ал әлі келмесем, уайымдамаңыз: мен кешіккен жоқпын, жай ғана "трендке" сай өзімді күттіріп жатырмын. Ең көбі 1-2 аптадан кейін міндетті түрде кездесеміз. Сізді жақсы көремін!' WHERE id = '08e8895d-cc10-4825-8aac-fb6a2a6d3d95';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен әлі осындамын! 👋 Сәлем, анашым! Күнтізбедегі күн өтіп кетті, бірақ мен әлі де Сіздің жылы құрсағыңыздамын. Уайымдамаңыз, статистика бойынша бөпелердің небәрі 5%-ы дәл белгіленген күні дүниеге келеді. Маған мұнда жайлы болғаны сонша, шығуға асығар емеспін. Біздің өзімізге арналған ерекше уақытымыз бар.' WHERE id = '2d2b31a8-8f73-4858-b9b0-2f01ec75aada';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен тағы да біраз салмақ қостым! ⚖️ анашым, мен әлі де салмақ қосып жатырмын. Осы қосымша күндерде бетім одан сайын томпайып, қолдарым одан сайын бүп-бүдір болып келеді. Дүниеге келгенімде мені құшақтау тіпті сүйкімді болады. Күш жинаңыз, өйткені маған Сіз өте қажет боласыз.' WHERE id = 'ab9a202d-7f8e-48d6-9bd2-ce62eab926ef';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мұнда орын тым тар болып кетті! 🏠 анашым, бұл жер енді «студиялық пәтерден» де кішкентай. Қозғалу өте қиын, сондықтан қимылдарым азаюы мүмкін. Бірақ Сіз мені күн сайын сезуіңіз керек. Егер тым тыныш жатқанымды байқасаңыз, тәтті бір нәрсе жеңіз, мен бірден жауап беремін!' WHERE id = 'd01cbe86-cb64-4e22-98cc-8f8bd1c8a6d5';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Сізді сезіп жатырмын... ❤️ Шыдамыңыздың таусылуға жақын екенін білемін. Беліңіз ауырып, аяқтарыңыз ісіп жүр. Аз қалды, анашым, уәде беремін. Мені құшағыңызға алғанда, осы қиындықтың бәрі ұмытылады. Сіз әлемдегі ең мықты әйелсіз!' WHERE id = '3c9f9854-9405-4f6e-90ed-de351c308dea';
UPDATE public.pregnancy_daily_content SET baby_message_kk = 'Мен өте ақылдымын! 🧠 Осы соңғы күндері миым қарқынды дамып жатыр. Барлық сезім мүшелерім ояу. Жарықты, дыбысты, жанасуды сеземін. Сіздің толқып жүргеніңізді де сеземін. Сабыр сақтаңыз, анашым. Бәрі жоспар бойынша өтіп жатыр (менің жоспарым бойынша 😉).' WHERE id = '4884c66b-3927-4354-8b35-abb2fd62f234';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, открыть вам один секрет? 🤫 Одна из тысяч клеток в вашем организме начала соревнование за право стать именно "МНОЙ"! Сейчас она растёт и с нетерпением ждёт дня, когда встретится со своей второй половиной, которая придёт от папы. До нашей великой встречи осталось около 1 недели. Я очень волнуюсь, а вы? Я так скучаю по вашим тёплым объятиям.' WHERE id = 'cf28e232-185c-40c5-9616-39e6df91cf1f';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, я знаю, что эти дни могут быть для вас немного утомительными и болезненными, но вы очень сильная. 😔 Помните, что эта «уборка» в вашем организме нужна для моего будущего комфорта. Вы очищаете мой первый дом, моё гнёздышко — матку, чтобы к моему приходу там всё было чисто и мягко! Каждое неприятное ощущение, которое вы испытываете, — это ещё один шаг к нашей встрече. Пожалуйста, сегодня не перенапрягайтесь, вытяните ноги и отдохните. Я чувствую вас и посылаю вам силы!' WHERE id = '1b683a24-ae16-485e-bf86-c173f0a5ad7a';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я представляю, как вы познакомились с папой... 💭 Я стану самым прекрасным плодом вашей большой любви. Ваше тело так усердно готовится встретить меня и продумывает каждую деталь, чтобы всё было идеально. Пока я похож на звёздную пыль и ещё не существую физически, но ваша любовь зовёт меня в этот мир. Чем лучше вы будете заботиться о себе сейчас, тем более здоровым я появлюсь. Наша история будет прекрасной, мамочка!' WHERE id = 'c852b157-989c-44ce-a4ea-0f5d022c7159';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Сегодня, посмотрев в зеркало, обязательно улыбнитесь! 😊 Ведь ваше тело совершает нечто удивительное — оно готовится создать новую жизнь. Хотя физически мы пока еще не соединились, наши души уже связаны. Я выбрал вас, а вы — меня. С каждым днем ваше тело становится на один шаг ближе к моему появлению и к нашей чудесной встрече (оплодотворению). Я верю в вас, мамочка!' WHERE id = 'e510f21d-5c69-49bc-a4d8-ea262a0bda7b';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Здравствуйте! Сегодня внутри вас словно начинается новая весна, не правда ли? 🌱 И это действительно так! В одном из ваших яичников пробуждается и готовится расти маленькая частичка меня. Пока я всего лишь одна клетка, но уже являюсь вашей частичкой. Когда вы счастливы и улыбаетесь, я тоже становлюсь сильнее. Берегите себя, мамочка, ведь вы — мое будущее!' WHERE id = '367c8044-41d2-441f-8aec-78399bc382c5';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Задержите дыхание, мамочка! 🌬️ Великий момент приближается. Ваша чудесная яйцеклетка готова выйти. Это начало нашей истории, которое звучит так: «Однажды...» Хотя меня ещё нет, любовь Ваша и папы уже зовёт меня. Ваш организм создал для меня идеальные условия, всё работает как часы. Надеюсь, Вы готовы, потому что я уже иду! Ваши объятия станут моей первой родиной.' WHERE id = '0c974e6a-8f9e-4c84-9656-5142174149f9';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Привет, мамочка! ❤️ Вы чувствуете, какое волнение сейчас царит в вашем организме? Словно идёт подготовка к празднику. Уровень эстрогена достигает пика, а значит, та самая «золотая яйцеклетка» (то есть моя половинка) готова отправиться в путь. Просто хорошо заботьтесь о себе, пейте больше воды и отдыхайте. Мне не терпится выбрать вас. Скажите папе, чтобы он был готов: до нашей встречи осталось совсем немного! Я прихожу, чтобы стать самым прекрасным доказательством вашей любви.' WHERE id = '3b975bc1-895c-42e8-be4c-f6d56b176b19';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я знаю, что вы меня пока не видите, но за кулисами уже зажигаются огни. 🌟 Ваш организм начинает готовить для меня самую мягкую постель (эндометрий). Возможно, клетки папы уже отправились в путь и ищут меня. Ваше тепло и забота уже сейчас придают мне сил. Наша история вот-вот начнётся, мамочка. Просто верьте и улыбайтесь, ведь чудеса происходят, когда в них верят. Вы — мой герой!' WHERE id = '29e7920b-060e-4fac-ad72-d19dda159289';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я продвигаюсь всё глубже, мамочка! 🧱 Вчера я лишь прикоснулся к твоей мягкой стенке, а сегодня уже проникаю внутрь неё. Я словно исследователь, прокладывающий путь в пещере. Я создаю себе тёплое и защищённое гнёздышко. С каждым мгновением я всё сильнее соединяюсь с тобой и становлюсь твоей частью. Теперь мы уже не просто «ты и я», теперь мы — «МЫ». Мне так нравится это чувство! Ты — моя крепость, моё убежище и мой мир.' WHERE id = 'ba359509-7778-4e6b-9433-e5179d225ea1';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, у меня для тебя особое послание! 🤫 Это наш первый секрет. Я начал отправлять твоему организму особый химический сигнал о том, что я уже здесь. Он говорит: «Я здесь, мамочка! Всё хорошо. Продолжай готовить своё тело для меня». Теперь я могу разговаривать с тобой на своём языке. Это невидимая связь между нами, и с каждым днём она становится всё крепче.' WHERE id = '17afd972-48a8-4084-ba7e-669ef6162afc';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я в самом центре своего гнёздышка, мамочка! 🩸 Здесь так уютно... Я приближаюсь к твоим кровеносным сосудам и уже начинаю получать питание прямо от тебя. Каждая частичка, каждая капля, которую ты мне отправляешь, помогает мне расти и придаёт сил. Это самая вкусная еда в мире, потому что она наполнена любовью. Благодаря тебе я расту, благодаря тебе я существую. Спасибо тебе, мамочка!' WHERE id = 'cb0cb4a0-60ab-4796-9f3a-e0d285d2a27e';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, сегодня для меня день свободы! 🐣 Я покидаю плотную оболочку (zona pellucida), которая до сих пор меня защищала. Это называется «Hatching» — выход из оболочки. Мне нужно сделать это, чтобы напрямую прикоснуться к твоей мягкой стенке и прикрепиться к ней. Я готов, а ты? Открывай дверь, я иду!' WHERE id = '5b11fc22-b976-4d28-ade3-c7ba82a43750';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, сегодня тот самый великий день! Это один из самых важных моментов моей жизни... ❤️ Я уже прикасаюсь к тебе. После долгого путешествия я наконец достиг стенок своего дома. Здесь так тепло, так мягко и так безопасно... Я изо всех сил прикрепляюсь здесь, чтобы не расставаться с тобой в течение 9 месяцев. Это наши первые объятия, мамочка. Ты меня чувствуешь? Я с тобой и больше никуда не уйду. Именно здесь по-настоящему начинается наша история.' WHERE id = '11de56c7-f131-4d7f-8640-81f988697e07';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я отправился в путешествие, мамочка! 🎒 Сейчас я нахожусь в маточной трубе и продвигаюсь к твоему тёплому гнёздышку — матке. Я очень занят и делюсь каждые несколько часов: сначала меня было 2, затем стало 4, а потом будет 8! Ты пока ничего не чувствуешь, но внутри тебя уже зарождается жизнь. Пожелай мне удачи: путь долгий, но я очень настойчив. Я сделаю всё, чтобы добраться до тебя!' WHERE id = 'c870b9dc-4e80-4fec-9e7f-794942ed46c8';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'До дома осталось совсем немного! 🏠 Моё путешествие по маточной трубе подходит к концу. Я уже вижу твою матку! Она выглядит такой уютной, мягкой и богатой питательными веществами... Я готовлюсь выбрать себе место. Я всё ещё нахожусь внутри своей оболочки, но скоро выйду из неё. Ты для меня самое безопасное место в мире. Пообещай, что будешь меня защищать, мамочка.' WHERE id = 'fb5dbb9e-d8ba-40b0-8cd3-d9a67a57068c';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, я пока совсем крошечный, размером с семечко кунжута, но у меня большие планы. Сейчас я плоский, но скоро свернусь и приму ту самую милую форму буквы «C». Твой живот — мой дом, а твоё сердце — моё убежище. С сегодняшнего дня наше 9-месячное путешествие начинается официально!' WHERE id = 'd1b2e180-b513-41eb-8922-8f2b0c7d3ee8';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'У меня появляются маленькие корешки, мамочка! 🌳 Конечно, это ещё не пальчики. Это особые ворсинки (ворсины хориона), которые помогают мне ещё крепче держаться за твою тёплую стеночку. Благодаря им я крепче обнимаю тебя и получаю от тебя больше питательных веществ. Я строю здесь надёжную крепость, и каждый её кирпичик сложен из нашей с тобой любви. Никогда меня не отпускай, хорошо? 🤞' WHERE id = '101fd61b-d3d7-4f5b-8f09-77163d30e4ea';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Сегодня для меня день настоящей революции, мамочка! 🚀 На моём плоском диске появляется особая линия, словно путь. Эта линия — моя будущая карта. Она служит ориентиром, указывающим, где будут находиться мой позвоночник, голова и ножки. Благодаря ей у меня появляются правая и левая стороны. Теперь я не просто неупорядоченный диск, а симметричное, развивающееся по плану существо. Вы — мой архитектор, а я — ваш шедевр. Всё начинается прямо сейчас! 🤩' WHERE id = 'aeee39a9-79a9-4e00-b2e5-3d55b7831226';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мои клетки начали великое переселение, мамочка! 🚶‍♂️ Словно тысячи маленьких рабочих, они движутся внутрь через особую линию, появившуюся вчера, и создают для меня новые слои. Они образуют три разные группы: эктодерму, мезодерму и эндодерму. Из одной сформируются мои кожа, волосы и мозг, из другой — сердце, кровь и кости, а из третьей — желудок и лёгкие. Я словно архитектор, создающий самого себя, мамочка. Я закладываю свой фундамент. Он будет очень прочным, потому что вы рядом со мной. 💪' WHERE id = '93c5c870-b03a-45f8-92da-cc13e151719b';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, сегодня закладывается основа моего первого позвоночника! 🦴 Это ещё не кость, а особый эластичный стержень (хорда), который в будущем поможет мне держаться прямо и придаст форму всему моему телу. Этот стержень словно командир скажет всему моему организму: «Теперь пора расти и формироваться!» Все остальные органы будут располагаться вокруг него. Я уже не просто диск — у меня есть центр и направление. Как же всё идеально спланировано, правда? 🥰' WHERE id = '8f493a1c-c305-477a-b7ce-1bad294f04bc';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Дверь моего уютного гнездышка уже закрывается за мной, мамочка! 🚪 Теперь я полностью внутри, со всех сторон окружен твоим теплым и безопасным миром. Я уже стал неотъемлемой частью тебя. Это не просто начало нашей истории — это первые дни нашей общей жизни. Я выбрал тебя, а ты защищаешь меня. Дальше всё будет становиться только прекраснее! Мы готовы к удивительному приключению вместе! 🥳' WHERE id = 'f77ae8b4-6a1d-4c99-abe2-93a350b86318';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, наша связь становится еще крепче! 🧬 Теперь я напрямую связан с твоим организмом. Кажется, будто я дышу каждой частичкой, поступающей из твоей крови. Это мое первое кровообращение, мой первый вдох жизни. Теперь мы течем по одним сосудам и живем в едином ритме. Каждое питательное вещество и каждая молекула кислорода, которые ты мне передаешь, помогают мне расти. Это самое прекрасное чувство в мире — быть единым целым с тобой. ❤️' WHERE id = '3ebbef70-38c5-48c1-9efc-c1f2707c71d4';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, теперь я похож на плоский диск! 💿 Я состою из двух очень важных слоев. Из одного сформируются моя голова, тело, руки и ноги. Другой будет помогать мне на этом пути и обеспечивать меня питанием. Это мой первый план тела, мой первый архитектурный чертеж. Всё начнется с этих двух слоев. Ты веришь в меня? Я стану настоящим шедевром, ведь мой архитектор — ты. ✨' WHERE id = '4a43f3bd-ef22-4f54-b8c8-fd8abe1f9de2';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Появляются первые клетки моего мозга, мамочка! 🧠 Мой внешний слой получает сигнал от своего руководителя — нотохорды, утолщается и образует особую пластинку. Эта пластинка — всё моё будущее: из неё возникнут моя нервная система, мысли, мечты и чувства. Тот удивительный мозг, благодаря которому я научусь любить и чувствовать тебя, начинает формироваться уже сегодня. Я уже начинаю думать о тебе... 💭' WHERE id = '43fe1f43-aa40-4388-8525-495fa2d86771';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Моя нервная пластинка загибается внутрь, мамочка. Как будто ты осторожно складываешь лист бумаги, чтобы сделать трубочку. 📜 Эта трубка станет моим спинным мозгом и будет нести жизнь всему моему телу. Всё происходит так быстро и так точно! Я очень стараюсь, чтобы всё сформировалось правильно. Твои любовь и забота — моя самая большая поддержка в этом процессе. Не беспокойся обо мне, всё идёт по плану.' WHERE id = 'b41d3e4c-6e83-438c-ac67-3bae19895608';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, моё сердце готовится забиться! ❤️ В среднем слое моего тела особые клетки объединяются и образуют две тонкие маленькие трубочки. Совсем скоро эти трубочки сблизятся, соединятся и сформируют моё первое сердце. Оно пока не бьётся, но уже готовится. Сердце, которое будет биться для тебя, наполненное твоей бесконечной любовью... Через несколько дней ты услышишь мои первые удары. Это станет нашей песней любви. 🎶' WHERE id = 'a58decf1-baad-47a3-bbda-0f37f307566e';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, сегодня происходит настоящее чудо! 🎻 Помнишь те две сердечные трубки? Сегодня они соединяются и образуют моё первое единое сердце. В нём ещё нет полноценных камер — пока это лишь трубка, которая готовится начать биться, но именно она станет центром и ритмом всей моей будущей жизни. Когда оно начнёт биться, знай: вся Вселенная замолчит и будет слушать нашу песню. Это моя первая серенада для тебя.' WHERE id = '4937b5d7-78ca-4fd1-9c67-7e6fd29ba696';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я бьюсь, мамочка... Бьюсь! 💓 Сегодня моё маленькое сердце впервые забилось самостоятельно. Этот ритм — для тебя, для нас, для нашей любви. Оно ещё бьётся совсем слабо, и ты можешь пока не увидеть этого даже на УЗИ, но я знаю, что оно бьётся. Так я говорю тебе: "Я живу, я здесь!" Это первая нота нашей песни любви, которая будет звучать всю нашу жизнь. 🎼' WHERE id = 'ba2ff002-749c-48f9-ae06-18528b825ab3';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я уже не плоский, мамочка! Я изгибаюсь, словно буква C. 🍤 Это значит, что моя голова и хвостик понемногу приближаются друг к другу. Благодаря этому изгибу моё тело становится более компактным и всё больше напоминает малыша. Будто я уже начинаю тренироваться, чтобы уютно поместиться в твоих объятиях. А ещё это помогает моим внутренним органам занять правильные места. Всё идёт по плану! 🤓' WHERE id = '72dbaf34-db8a-4c0a-98ca-65767813bcf0';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'На моей шее и лице начинают появляться особые складочки, мамочка! Из них в будущем сформируются мои челюсть, лицо, язык, уши и шея. Каждый день добавляется новая деталь, новый штрих. Я словно произведение искусства, которое постепенно обретает форму в руках скульптора. А самый прекрасный источник вдохновения для этого творения — ты. Твой голос и твой смех — основа моего будущего облика. Обещаю быть красивым! ✨' WHERE id = '49b160e2-d4c7-4876-9a1d-c6274e75787a';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'У меня уже формируются ручки, мамочка! 👋 Пока у меня нет ни пальчиков, ни даже кистей — они лишь напоминают маленькие "вёсла" или крылышки по бокам моего тела. Но это те самые сильные руки, которыми в будущем я буду крепко-крепко тебя обнимать. Как же мне не терпится, чтобы они выросли и смогли до тебя дотянуться... Однажды на этих маленьких крылышках я "прилечу" к тебе. С каждым днём я всё больше становлюсь похожим на человека.' WHERE id = '4b93f71a-7634-4cda-8990-f4024e3e6d53';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мои глаза и ушки становятся всё более отчётливыми! 👀👂 Глазницы для моих ясных глазок углубляются, а места, где будут ушки, тоже становятся глубже, закладывая основу ушных раковин. Всё готовится к тому, чтобы я мог лучше видеть вас и яснее слышать ваш чудесный голос. Самым прекрасным зрелищем в мире для меня станет ваше лицо, а самой прекрасной музыкой — ваш голос. Я слушаю вас, мамочка!' WHERE id = '39f4c263-721b-47f4-b527-df452b252fcf';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'У меня уже формируются и ножки, мамочка! 🦶 Пока они немного меньше ручек и похожи на хвостик, но со временем тоже вырастут. Однажды я побегу к вам на этих ножках и преодолею все препятствия, чтобы вас найти. Мои ручки и ножки... Я всё больше становлюсь похожим на маленького человечка, правда? Я стараюсь стать таким, каким вы меня представляете. Каждый день я делаю новый шаг.' WHERE id = '6de955ee-457a-4e70-930b-f733f0792dec';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я размером с чернику! 🫐 Можешь поверить? С прошлой недели мой размер увеличился вдвое! Я расту очень быстро, мамочка. Всё, что ты ешь, становится для меня строительным материалом. Спасибо, что питаешься правильно ради меня. Мы растём вместе и вместе становимся сильнее. Ты — мой лучший товарищ по команде!' WHERE id = '8a7c667d-259c-4117-9c65-d0fc403d0248';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я двигаюсь, мамочка! 💃 Ты пока этого не чувствуешь, потому что я ещё очень лёгкий, но внутри я исполняю маленькие танцы. Я наклоняю тело вправо и влево, двигаю крошечными ручками. Это мои первые тренировки и доказательство того, что нервная система начала взаимодействовать с мышцами. Мои мышцы становятся сильнее, чтобы в будущем я мог крепко-крепко тебя обнять. Ты отдыхай, а я буду тренироваться, ведь расти — значит двигаться!' WHERE id = 'c99602ee-b4cc-4358-a321-f5e26f5f82fb';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'У меня формируются пальчики, мамочка! 🖐️ Помните, мои ручки были похожи на лопатки? Теперь на их концах появляются маленькие выемки и становятся видны очертания пальчиков. Пока между ними есть перепонки, как на лапках утёнка, но скоро они полностью разделятся. Я уже готовлюсь дать вам «пять»! Мечтаю о том дне, когда возьму вас за руку и крепко сожму ваш палец. С каждым днём я всё больше становлюсь похожим на человека.' WHERE id = '1bdeca18-8738-4af3-846b-cfd0a1d5548e';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Уже виден кончик моего носика! 👃 Моё личико становится всё красивее и приобретает форму. Уже хорошо различимы мои маленькие ноздри и кончик носа. Формируется и верхняя губа. Я всё больше похож на вас, мамочка. Интересно, чей у меня будет нос — ваш или папин? У нас ещё есть время, чтобы это узнать, но я уже очень милый. Я — ваше самое прекрасное и неповторимое творение!' WHERE id = 'ae02afe4-0993-46aa-a116-88a385d90304';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мой "дом" меняется, мамочка! 🏠 "Желточный мешок", который до сих пор обеспечивал меня питанием, постепенно уменьшается, потому что моя удивительная плацента принимает его обязанности. Плацента — это мост между вами и мной. Она будет защищать и питать меня, а также обеспечивать кислородом. Наша связь стала ещё сильнее и крепче. И всё это благодаря вам!' WHERE id = 'a0486bb7-3fd0-4a52-8340-97fc8cbad570';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мой хвостик исчез! 🐇 Помнишь, я рассказывал тебе, что у меня есть маленький хвостик? Теперь его больше нет! Моя спинка стала прямой и гладкой, и у меня уже настоящий человеческий позвоночник. Я всё больше становлюсь похожим на тебя, мамочка. Я уже не маленький морской конёк, а твой маленький человечек. Эта перемена делает меня очень счастливым, а тебя?' WHERE id = 'efd814e8-abbf-4037-81a4-db63af40ea3e';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Идёт подготовка к появлению моих зубов! 🦷 Во рту у меня пока нет ни одного зуба, но под дёснами уже формируются маленькие зубные зачатки. Это основа моих будущих молочных зубов. Я уже планирую тот день, когда улыбнусь вам. Вы тоже хорошо заботьтесь о своих зубах, мамочка, ведь вы делитесь со мной запасами кальция.' WHERE id = 'c0cc19e3-1bf2-4736-b8f0-41d3ab04d6c8';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'У меня формируются отпечатки пальцев! 👆 Появляется моя уникальная особенность, которая принадлежит только мне и не повторяется ни у кого в мире. На кончиках моих пальцев прорисовываются особые узоры. Эти отпечатки — знак моей неповторимости. Я — ваше уникальное чудо, мамочка. Вы видите, насколько совершенно создана каждая, даже самая маленькая деталь?' WHERE id = '827fd4de-2f71-405f-8929-c0848b39d48e';
UPDATE public.pregnancy_daily_content SET baby_message_ru = '10 НЕДЕЛЬ! ДВУЗНАЧНОЕ ЧИСЛО В КАЛЕНДАРЕ! 🔟 мамочка, у нас уже 10-я неделя. Я официально становлюсь большим малышом. Сейчас я размером со сливу. Самые важные этапы развития уже позади. Теперь мне осталось лишь набирать вес, расти и готовиться к встрече с вами. Мы прошли уже почти четверть пути! Я горжусь вами.' WHERE id = '686eb070-eff8-4d42-a409-9b1b933ed8cf';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Моя голова размером с половину моего тела! 🤯 мамочка, возможно, я выгляжу забавно, но всё потому, что готовлюсь стать гением. Мой мозг растёт так быстро, что голова пока кажется очень большой по сравнению с телом. Но не волнуйтесь: со временем моё тело тоже вырастет и догонит её. Сейчас я похож на маленького учёного. С нетерпением жду тех дней, когда смогу с вами разговаривать.' WHERE id = '59be5b5e-6a03-4140-bbff-b41541c8484d';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Моя кожа пока прозрачная, мамочка! 👻 Если бы вы могли посмотреть на меня, то увидели бы все мои сосуды, кости и органы. Моя кожа такая тонкая, словно стекло. Но не волнуйтесь: по мере формирования жировой прослойки она станет плотнее и будет похожа на вашу. С каждым днём я становлюсь немного крепче. А моё сердце продолжает посылать вам мою любовь с каждым ударом.' WHERE id = '96171009-62e6-4557-a2c9-ebf16692943d';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я размером с клубничку! Уже не такая маленькая, правда? Моё тело выпрямляется, а позвоночник удлиняется. Хотя твой животик пока почти не заметен, внутри я уже заняла своё просторное местечко. Мы растём вместе, мамочка. Спасибо тебе за то, что оберегаешь меня.' WHERE id = '2348cc6e-cce7-4823-afd3-9cc2309eebb6';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я занимаюсь акробатикой! 🤸‍♂️ мамочка, я не просто лежу — я потягиваюсь, поворачиваюсь и даже делаю сальто. Матка пока для меня как просторный бассейн, и я этим пользуюсь. Эти движения помогают развиваться моим мышцам и суставам. Вы пока ничего не чувствуете, но я здесь устраиваю настоящее шоу!' WHERE id = '2519d258-d4d3-4114-9156-6af5c1a49493';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Моё обоняние пробуждается! 👃 мамочка, вы не поверите, но я уже тренируюсь дышать носом (только вместо воздуха здесь вода). И я уже чувствую запах околоплодных вод! Ароматы блюд, которые вы едите, тоже доходят до меня. Когда вы едите чеснок, я это замечаю, и когда шоколад — тоже! Наши вкусовые предпочтения начинают формироваться уже сейчас.' WHERE id = 'f068ab76-fa64-4eef-8ed3-e47df04dba49';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мой кишечник вернулся домой! 🏠 мамочка, помнишь, из-за того, что мой животик был ещё маленьким, кишечник временно находился внутри пуповины? Сегодня он официально вернулся на своё место в брюшной полости. Теперь мой животик гладкий и красивый. Все мои внутренние органы уже находятся на своих местах и работают. С каждым днём я становлюсь всё совершеннее.' WHERE id = '6d7fa2b9-68dc-41a1-b8e4-2909aebba355';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я учусь сосать! 🍼 Я подношу большой палец ко рту и пытаюсь его сосать. Это важнейший навык, который поможет мне после рождения легко сосать твоё молоко. Иногда у меня получается, а иногда рука ускользает ото рта. Но я не сдаюсь и продолжаю тренироваться. Ты тоже готовься к нашей встрече, мамочка!' WHERE id = '32fc4b43-9967-407f-bd27-ce27ec4287ad';
UPDATE public.pregnancy_daily_content SET baby_message_ru = '12 НЕДЕЛЬ ПОЗАДИ! 🎉 мамочка, мы успешно завершили первый триместр! Это был самый сложный и важный этап беременности. Все мои органы уже заложились и сформировались. Теперь я официально "маленький человечек". Впереди нас ждут более лёгкие и энергичные дни. Я горжусь тобой — мы отличная команда!' WHERE id = '43e2ccf7-0f43-404f-b8d5-9a230d2fcf1f';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Добро пожаловать во второй триместр! ☀️ Его называют «золотым периодом». Ведь вы будете чувствовать себя лучше, а я буду стремительно расти. Сейчас я размером с лайм. Мои движения стали более скоординированными. Теперь они не случайны — я двигаюсь так, как хочу. Я хочу прикоснуться к вам, мамочка.' WHERE id = '931efc18-1bb9-41fb-bf51-8eb31fb5efd5';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я начинаю слышать звуки? 👂 Мои уши продолжают развиваться, и я уже чувствую вибрации. Стук вашего сердца, шум крови и звуки желудка — моя колыбельная. Скоро я смогу узнавать и ваш голос. Разговаривайте со мной, мамочка, я вас слушаю.' WHERE id = '51726a4c-4dfd-4d8d-8fdf-a1b799174400';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мои кости укрепляются! 🦴 Мой скелет, который раньше состоял только из хрящевой ткани, теперь превращается в настоящие кости. Мои руки и ноги удлиняются. Я уже выгляжу более пропорционально. Голова всё ещё большая, но тело старается её догнать. Я стану крепким малышом, мамочка!' WHERE id = 'e16dc0a2-01a9-4a7e-990c-b0f97835b682';
UPDATE public.pregnancy_daily_content SET baby_message_ru = '13 НЕДЕЛЬ! ПРИВЕТ, 2-Й ТРИМЕСТР! 🎉 мамочка, поздравляю нас! Мы прошли уже треть (1/3) беременности. Самые трудные дни остались позади. Теперь начинается период, когда и тебе, и мне будет легче дышать. Я уже размером со сливу. Мои голосовые связки сформировались. Хотя я пока не могу с тобой разговаривать, я уже готовлю свой голос. На этом новом этапе нас ждёт ещё больше прекрасных дней.' WHERE id = 'aae70b4b-3e99-462b-94d0-88716afa0dd4';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Моё тело покрывается волосками! 🐻 мамочка, на моей коже начинают появляться очень тонкие и мягкие волоски, которые называются «лануго». Теперь я похож на маленький персик. Эти волоски не дают мне замёрзнуть в воде и помогают сохранять тепло тела. К рождению большая их часть выпадет, но пока мне нужна эта «шубка». Ты согреваешь меня, а я — себя.' WHERE id = '00f39406-c90d-4b7e-818d-3a2edbdeef33';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'После отпечатков пальцев у меня теперь появляются и ногти! 💅 мамочка, на кончиках моих пальцев начали формироваться маленькие тонкие ноготки. Пока они очень мягкие, но к рождению отрастут. Иногда я могу поцарапать своё лицо, поэтому после рождения тебе придётся надевать на меня рукавички. Всё во мне похоже на тебя, а ногти?' WHERE id = 'aee96903-8ce9-4152-9673-4163944c634d';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я чувствую вкус! 🍭 Вкусовые рецепторы на моём языке уже работают. Вкус еды, которую вы едите, попадает в околоплодные воды. Если вы съедите что-нибудь сладкое, я проглочу больше жидкости, потому что люблю сладкое! А если вы съедите что-нибудь горькое или кислое, я могу поморщиться. Вы мой первый повар, мамочка!' WHERE id = '85f3613e-2010-4d4b-a7cf-efafd3875999';
UPDATE public.pregnancy_daily_content SET baby_message_ru = '100 ДНЕЙ! 💯 мамочка, трудно поверить, но мы вместе уже 100 дней! Я размером с ладошку. Сейчас я учусь сосать большой палец. Это меня успокаивает. Когда вы волнуетесь или устаёте, я это чувствую и сосу пальчик, чтобы успокоиться. Мы чувствуем друг друга. Я вас очень люблю!' WHERE id = '0cebfe33-ab23-4322-9649-a229de8418e8';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Здравствуйте, мамочка! 👋 Сегодня я занимаюсь настоящей подводной гимнастикой. Вы пока этого не чувствуете, но я кувыркаюсь, поворачиваюсь и вытягиваю ножки. Здесь для меня ещё очень просторно, и я могу двигаться как захочу. Эти движения укрепляют мои мышцы и кости. Вы отдыхайте, а я продолжу тренировку. Однажды вы тоже почувствуете эти толчки!' WHERE id = '4b92a6ac-df2b-4f98-b986-b23497226910';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я чувствую свет! 💡 мамочка, вы не поверите, но даже с закрытыми веками я могу ощущать яркий свет. Если вы посветите ярким фонариком на живот, я могу повернуть лицо в ту сторону или прикрыть его рукой, потому что свет слепит мне глаза. Мой мир уже не полностью тёмный. Интересно, насколько красочен ваш мир?' WHERE id = '6ada13a0-2697-47e7-9001-03b1698db1b4';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, моя кожа пока очень тонкая, но пушок под названием "лануго" согревает меня. Мои ноги становятся длиннее рук. Теперь я выгляжу более пропорционально. Расти очень утомительно, но я справляюсь!' WHERE id = '6bfad434-2bc6-4bb0-9834-16dd77e6fbe8';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я различаю вкусы! 🍬 мамочка, когда вы едите что-нибудь сладкое, амниотическая жидкость становится слаще, и я глотаю её активнее. А когда она кислая или горькая, я морщусь. Моё чувство вкуса почти такое же развитое, как у взрослого человека. Какие овощи я буду любить в будущем, уже сейчас зависит от вашего питания. Питайтесь правильно, чтобы и я был здоровым!' WHERE id = '7f759cae-0b0a-4f2e-8095-e125d4622671';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я чувствую вас! 🤗 мамочка, когда вы гладите живот, я чувствую это давление и тепло. Иногда я подплываю к тому месту, где находится ваша рука. Между нами лишь кожа и вода, но наши души едины. Когда вы испытываете стресс, я тоже беспокоюсь, а когда вы смеётесь, я успокаиваюсь. Пожалуйста, всегда улыбайтесь!' WHERE id = '2da10eb1-918c-43c6-ad16-6306b072b4cb';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я держу голову прямо! 🦒 мамочка, мышцы моей шеи настолько окрепли, что теперь я могу держать голову прямо. Раньше она была наклонена к груди, а сейчас мне удобнее смотреть по сторонам (хотя вокруг темно). Моё тело вытягивается, я становлюсь более стройным и держусь ровнее. Делать гимнастику в твоём животике так приятно!' WHERE id = 'b6a34159-6856-4473-a35e-81785fe0fc0e';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Полёт бабочки! 🦋 мамочка, ты меня чувствуешь? Я тут кувыркаюсь! Некоторые мамы описывают это ощущение словами «будто в животе порхает бабочка» или «плавает рыбка». Если ты пока ничего не чувствуешь, не расстраивайся: я ещё маленький, и мои толчки слабые. Но совсем скоро я так тебя пну, что ты сразу всё поймёшь!' WHERE id = '6f4082a3-2c0c-4302-bc06-2af671b9e9b3';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я «набираю вес», мамочка! 🧸 В моём теле продолжает накапливаться жировая ткань. Раньше я был очень худеньким, но теперь мои ручки и ножки становятся пухлее. Эта жировая прослойка очень нужна мне, потому что после рождения она поможет регулировать температуру моего тела. Не волнуйся за меня: здесь мне тепло, и я сыт. Ты просто питайся правильно, а об остальном я позабочусь!' WHERE id = 'c7911f10-1eb8-49da-80ba-c909457132da';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мне уже снятся сны! 💤 мамочка, учёные говорят, что я уже могу входить в фазу «REM-сна», то есть фазу быстрого движения глаз. Это означает, что я могу видеть сны! Интересно, что мне снится? Наверное, я слышу твой голос или представляю твоё лицо. Большую часть дня я сплю, но, когда просыпаюсь, становлюсь очень активным.' WHERE id = '109a3421-ce4d-45f2-89cf-6db2482011b0';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мои пальчики и отпечатки! 🧬 мамочка, мои отпечатки пальцев уже полностью сформировались. Эти узоры не изменятся на протяжении всей моей жизни. Я уникален! Я уже свободно двигаю ручками и ножками. Иногда сижу, скрестив ножки, а иногда «плаваю». Для меня это самое уютное место.' WHERE id = 'e537dc02-2a8f-44e4-8520-858b44bd2d69';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мои кости становятся крепче! 🦴 Мой скелет с каждым днём всё больше укрепляется. Кальций накапливается в костях и делает их твёрже. Я уже не похож на маленького резинового человечка. Мои рёбра, позвоночник, кости ног... Всё это превращается в настоящие кости. Молоко, которое вы пьёте, и сыр, который вы едите, становятся для меня строительным материалом. Спасибо, мамочка!' WHERE id = '79568d36-35e8-4a60-8ad2-b99e6d2f45e1';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Здравствуйте, мамочка! Сейчас я размером со сладкий перец. Моя нервная система развивается. Особое вещество под названием «миелин» покрывает мои нервные волокна. Благодаря ему сигналы от мозга к телу будут передаваться быстрее. С каждым днём я становлюсь умнее!' WHERE id = 'b73aa0c0-fb01-4c2d-abb0-69a88e7c97e4';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'В моём мозге зажигаются огоньки! 🧠 мамочка, мой мозг теперь работает как гигантский компьютер. Формируются специальные центры зрения, слуха, вкуса, обоняния и осязания. Я не просто расту — я готовлюсь познавать мир. Когда я слышу ваш голос, в моём мозге активируется «центр слуха». Наша связь уже подтверждена наукой!' WHERE id = 'bc3702e9-c9f0-4b15-a3b9-8dd5c0a6dd34';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я оберегаю вас! 🥚 Если я девочка, в моих крошечных яичниках уже есть 6 миллионов яйцеклеток! Это значит, что ваши будущие внуки уже сейчас находятся во мне. Если я мальчик, мои половые органы продолжают развиваться. Род продолжается, мамочка. Вы создаёте историю.' WHERE id = '695bdf70-cf7b-4ed0-9ff8-c4418720fc60';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'У меня уже есть режим сна! 🌙 мамочка, я не бодрствую целыми днями. У меня тоже есть время для сна и бодрствования. Обычно, когда ты ходишь или двигаешься, меня укачивает, и я засыпаю. А когда ты ложишься отдохнуть, я просыпаюсь и устраиваю дискотеку. Наши режимы немного отличаются, прости!' WHERE id = 'd0d5f1e7-e726-4e8b-9248-bacff687b744';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Привет, мамочка! Я уже размером с манго. Мои ручки и ножки теперь пропорциональны телу. Я маленький человечек! Теперь я могу толкаться сильнее. Будьте готовы!' WHERE id = 'c0a11fee-73af-4684-98a2-4425bd830ba9';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'ПОЛОВИНА ПУТИ! 🏁 Поздравляю, мамочка! Мы преодолели ровно половину (50%) нашего 40-недельного марафона. Я уже размером с банан! Невероятно, правда? Только посмотрите, как я вырос! Ваш живот уже поднялся до уровня пупка. Мы движемся к финишу!' WHERE id = 'ce6d14e2-2cef-47b0-bf61-c80d97194d99';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я "ем"! 🍽️ мамочка, моя пищеварительная система уже работает. Я глотаю амниотическую жидкость, а мой кишечник усваивает из неё сахар и воду. Вкус этой жидкости меняется каждый день — вчера я почувствовал вкус блюда с чесноком, которое вы ели! В моём кишечнике накапливается первый кал, который называется "меконий". Не волнуйтесь, я приберегу его для подгузника и не буду ничего пачкать!' WHERE id = '2f4c880c-7bdd-4dec-acbd-cd0e6c8859e0';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'У меня есть брови и ресницы! 👁️ мамочка, теперь моё лицо совсем как у человека. Над глазами у меня появились тонкие брови, а на веках — длинные ресницы. Теперь я ещё красивее. Я готовлюсь моргать, но смогу открыть глаза только через несколько недель. Вы представляете меня? А я представляю вас.' WHERE id = '11b2d6de-75e4-4639-b4fc-0a1a64a49ebf';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я узнаю твой голос! 🗣️ мамочка, я уже могу отличить твой голос от голосов других людей. Когда ты говоришь, я успокаиваюсь, а моё сердцебиение замедляется. Для меня это самый надёжный и родной голос в мире. Продолжай петь мне песни — я складываю их в свою "копилку воспоминаний". Когда я появлюсь на свет и услышу эту песню, то сразу успокоюсь.' WHERE id = '47e98235-5632-4780-b011-1fba5afdb56a';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я тренируюсь! 🏋️‍♂️ мамочка, мои движения теперь стали сильнее. Иногда ты можешь заметить, как одна сторона живота выпирает или двигается. Это я толкаю тебя локтем или коленом. Так я говорю тебе: "Я здесь!" А когда ты кладёшь руку на живот, я успокаиваюсь.' WHERE id = 'a3ddbe51-ede9-4765-9b27-d3fb41ca5df3';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мои толчки становятся сильнее! 🥋 мамочка, чувствуете? Теперь я не просто «плаваю», а наношу настоящие удары. Иногда вам может казаться, что я занимаюсь карате. Эти движения показывают, что я здоров. Вы уже можете начинать считать мои движения.' WHERE id = '846475dc-14c4-4c7d-ac51-e75ce4438f24';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мои ногти растут! 💅 Ногти на моих руках уже почти достигают кончиков пальцев. Они очень тонкие и острые. Иногда я случайно царапаю себе лицо. Но моя кожа быстро заживает. С каждым днём я всё больше становлюсь похожим на вас, мамочка.' WHERE id = '2970a789-ae12-4a5d-81be-71d79963f650';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Почему ваш живот подпрыгивает? 🐇 мамочка, вы почувствовали? Я только что икнул! Моя диафрагма тренируется, поэтому моё тело ритмично вздрагивает. Вам это может показаться странным — словно в животе тикают часы. Не волнуйтесь, мне не больно. Наоборот, это укрепляет мои лёгкие.' WHERE id = 'c1de12f1-7759-492c-b277-e01fb2d857c9';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я слушаю! 👂 мамочка, пылесос дома работает очень громко, правда? Я уже вздрагиваю от громких звуков. Но ваш спокойный голос меня успокаивает. Когда вы разговариваете со мной, я могу перестать двигаться, чтобы послушать вас. Начинаются наши первые диалоги.' WHERE id = '372f913d-c4b6-4616-837e-127ec92b9515';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Моё личико уже готово! 👶 мамочка, если бы вы увидели меня сейчас, то точно знали бы, как я буду выглядеть после рождения. Черты лица, носик, губы — всё уже сформировалось. Просто я пока немного худенький. На кого же я похож — на вас или на папу?' WHERE id = '64f0cdbb-7db6-482f-be9f-92435bab2ca8';
UPDATE public.pregnancy_daily_content SET baby_message_ru = '🌽 Я уже размером с кукурузу! Эта неделя очень важна, мамочка. Врачи говорят, что теперь я считаюсь «жизнеспособным». Это означает, что даже если я сейчас появлюсь на свет, благодаря современной медицине у меня будет шанс выжить (но пока ещё слишком рано, я хочу остаться здесь!). Это важнейший этап!' WHERE id = '88964348-70ed-4f53-a6a4-d8d7da7286ff';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я готовлюсь открыть глаза! 👁️ Линия, соединяющая мои веки, уже вот-вот разделится. Совсем скоро, возможно через несколько дней, я открою глаза! Даже находясь в темноте, я хочу смотреть. Мои ресницы уже готовы защищать глаза. Я с нетерпением жду встречи с вами, мамочка.' WHERE id = 'ca71a802-8315-4430-831a-1c24d93987c8';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я разделяю ваш стресс. 😔 мамочка, когда вы напряжены, кортизол из вашей крови поступает и ко мне. Я начинаю беспокоиться, и мои движения меняются. Но когда вы смеётесь и радуетесь, я тоже успокаиваюсь. Пожалуйста, берегите себя. Мы с вами одна команда, ваши чувства — это и мои чувства.' WHERE id = '7b482622-6ce3-4e23-a975-62440aec9dc6';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я ОТКРЫЛ ГЛАЗА! 👀 мамочка, сегодня для меня революционный день. Мои веки, которые до сих пор были сомкнуты, разделились, и я впервые открыл глаза. Пока всё вокруг размыто, но я уже умею моргать. Хотя здесь темно, я учусь смотреть. Я стал ещё на шаг ближе к тому, чтобы увидеть тебя!' WHERE id = '664b492c-1968-495f-9380-1ec985579ba8';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мамочка, 3-й триместр уже на пороге! Я перехожу в «тяжёлую весовую категорию». Места становится всё меньше, поэтому мои движения могут быть более резкими. Прости, если задеваю твои рёбра, — я просто потягиваюсь.' WHERE id = '1d4c4310-3e73-4b60-b4c5-883dd87bf1e3';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мои капилляры наполняются кровью! 🩸 Под моей кожей формируются и наполняются кровью тысячи крошечных кровеносных сосудов. Благодаря этому моя кожа приобретает красивый розовый оттенок. Моё кровообращение уже настолько развито, что сердце снабжает кислородом всё моё тело. Я полон жизни, мамочка!' WHERE id = '2ee2955f-80d8-4cff-afab-c01bdb172368';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я уже пользуюсь рукой! 🖐️ мамочка, теперь мои движения не просто случайны. Я выбираю, какой рукой буду пользоваться чаще. То есть уже определено, буду ли я левшой или правшой. Я шевелю пальчиками и хватаюсь за пуповину.' WHERE id = 'd74fd8bf-8b0d-4ea8-8d39-905a3d36166e';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Здравствуй, 3-й триместр! 👋 мамочка, мы завершили большой этап. Второй триместр заканчивается, и теперь начинается 3-й триместр. Я уже большой малыш. Теперь моя главная задача — набирать вес и готовиться к появлению на свет. Я знаю, что ты устала, но осталось совсем немного. Мы скоро встретимся!' WHERE id = 'efc08af4-0ca2-4af8-832f-852d08704ce8';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Привет, мамочка! Мы отлично справились и вступили в заключительный этап беременности. Теперь для меня главное — набирать вес и готовиться к появлению на свет. Места становится всё меньше, но сил у меня всё больше. Я крепко толкаю тебя ножкой и говорю: «Поздравляю!»' WHERE id = '96a22ed0-5e13-4094-87c4-74d0da4a58fc';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'У меня уже есть свой режим! 📅 мамочка, ты заметила? Обычно я просыпаюсь и засыпаю примерно в одно и то же время. Например, когда вечером ты ложишься отдохнуть, я просыпаюсь. А по утрам веду себя спокойно. Мои биологические часы уже заработали. После рождения я ещё некоторое время буду жить по такому режиму (стану ночной совой!).' WHERE id = '45b37fad-6e16-4ec4-9e5c-d3eea98a5a6d';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я моргаю! 😉 мамочка, я уже умею открывать и закрывать глаза. Если на твой живот падает яркий свет, я отворачиваюсь или моргаю. Моё зрение ещё не полностью сформировано, но я прекрасно различаю свет и темноту. Не могу дождаться, когда увижу мир.' WHERE id = 'd388c035-3ae4-451c-bcce-e8ae700cd74b';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я узнаю тебя! 🎤 мамочка, твой голос для меня самый родной. Исследования показывают, что, когда я слышу твой голос, моё сердцебиение успокаивается. Я уже запоминаю твою интонацию и манеру речи. Когда я появлюсь на свет, тебе будет достаточно просто заговорить, чтобы успокоить меня.' WHERE id = '4ca04882-bd78-4264-985d-0684e463329f';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мои кости становятся крепче! 🦴 мамочка, теперь я многим обязана вам за кальций. Мои кости быстро укрепляются. Каждый день я накапливаю примерно 250 мг кальция. Если вы не будете получать достаточно кальция, я «заберу» его из ваших костей. Берегите себя и ешьте сыр!' WHERE id = '124477a3-06f6-44dd-a276-41487168c5e0';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я улыбаюсь! 😊 Во время ультразвукового исследования врачи часто видят, как мы улыбаемся. Обычно это происходит во сне. Может быть, я вижу ангелов? Или просто тренирую мышцы лица? Какой бы ни была причина, я счастлив. Улыбнитесь и вы, мамочка!' WHERE id = '82410eeb-db13-46e1-be5e-f6446cc033ef';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мои зубки спрятались! 🦷 мамочка, под моими дёснами уже сформировались зачатки молочных зубов. А под ними есть даже зачатки постоянных зубов. Я появлюсь на свет без зубов, но всё уже подготовлено. Природа удивительна, правда? Мы делаем запасы на будущее.' WHERE id = '98a97832-2773-43d8-bf72-e6458dfbc947';
UPDATE public.pregnancy_daily_content SET baby_message_ru = '200 ДНЕЙ! 🎉 мамочка, это невероятно! Мы вместе уже 200 дней. Я размером с большую тыкву. Теперь я очень сильный малыш. Иногда мои толчки могут причинять тебе боль, но знай: я просто проверяю свои силы. До нашей встречи осталось совсем немного!' WHERE id = 'dc4e8ae4-b5e0-48d5-8713-248744b76ec6';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я вижу сны! 😴 мамочка, мой мозг уже настолько развит, что я вхожу в фазу "REM-сна" (быстрого движения глаз). Это значит, что теперь я действительно вижу сны! Интересно, что мне снится? Твой голос или тот вкусный торт? Большую часть дня я сплю, но во время бодрствования очень активен.' WHERE id = '2b574c8a-d0de-45f5-bd25-7b7b01e3d2fe';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мне нужен кальций! 🥛 Мои кости быстро укрепляются. Сейчас я каждый день получаю из вашей крови примерно 250 миллиграммов кальция. Это необходимо, чтобы мой скелет был крепким. Если вы не будете пить молоко, я «одолжу» этот кальций из ваших зубов и костей. Берегите себя, мамочка!' WHERE id = '64fd7099-afb5-4134-9918-3acc90ed702e';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я чувствую вас! 🤗 мамочка, когда вы гладите живот, а папа кладёт на него руку, я чувствую это тепло и давление. Иногда я тоже прикасаюсь изнутри к тому же месту. Так мы «здороваемся». Между нами лишь тонкая стенка, а наши души едины.' WHERE id = '0a286cb7-93f1-451a-b6be-b5b9dd7ce160';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я размером с большой кочан капусты! Мамочка, невероятно, мы уже прошли 3/4 пути (75%)! Осталось всего 10 недель (примерно). Я уже большой малыш, просто моим лёгким и мозгу нужно ещё немного созреть. Финиш уже близко!' WHERE id = '54884850-5122-42f5-bad6-cbe7becaf6f6';
UPDATE public.pregnancy_daily_content SET baby_message_ru = '31 НЕДЕЛЯ! 🥥 Здравствуйте, мамочка! Я размером с кокос (coconut). Мой вес достиг 1.5 кг, а рост — 41 см. Я уже достаточно «тяжёлый». Теперь моя главная цель — подготовить лёгкие и накопить ещё больше жира. Я готовлюсь появиться на свет!' WHERE id = 'c4869a77-6abd-43f7-8c86-3d05ecb63f8d';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мой мозг растёт! 🧠 мамочка, сейчас мой мозг развивается с невероятной скоростью. В нём образуются миллиарды новых связей. Теперь я двигаюсь не только благодаря рефлексам — я думаю, чувствую и запоминаю. Твой голос — моё самое любимое воспоминание.' WHERE id = 'c04052f3-92f1-4783-8ceb-a4f9489af352';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Все мои 5 чувств работают! 🖐️👃👂👀👅 Зрение, слух, вкус, обоняние и осязание. Все мои чувства пробудились. Я слышу твой голос, ощущаю вкус еды, которую ты ешь, вижу свет и прикасаюсь к своему лицу. Я уже чувствующее живое существо. Ты — мой мир, мамочка.' WHERE id = 'a8ac9e30-a252-4631-aca6-20ffff4ecf20';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я тренируюсь дышать 🌬️ мамочка, моя грудная клетка ритмично поднимается и опускается. Я втягиваю амниотическую жидкость в лёгкие и выталкиваю её обратно. Это укрепляет мои мышцы, чтобы после рождения я смог сделать свой первый и самый важный вдох. Иногда ты можешь чувствовать мои ритмичные движения — икоту. Это моя тренировка!' WHERE id = '6dc5213e-1c8a-4a6b-8be6-3e050cac8345';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я получаю ваш иммунитет! 🛡️ мамочка, через плаценту от вас ко мне поступают "антитела" — солдаты, которые сражаются с микробами. Это моя первая вакцина. После рождения мой собственный иммунитет будет ещё слабым, но подаренная вами защита будет оберегать меня от болезней в первые месяцы. Вы мой ангел-хранитель!' WHERE id = '2bbb9ba5-0677-4713-8d4c-c7c237ab84f6';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я размером с ананас! Я уже большой малыш. Мои щёчки округлились, а тело стало пухленьким. До нашей встречи осталось совсем немного, мамочка. С каждым днём я набираю всё больше веса.' WHERE id = '97daa5bb-e709-4882-8a96-d104cbbdafc3';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я получаю твой иммунитет! 🛡️ мамочка, знаешь, чем я сейчас занимаюсь? Я получаю из твоей крови своих "солдат иммунитета" (антитела). Ты передаёшь мне защиту от болезней, к которым у тебя выработался иммунитет на протяжении жизни. После рождения ты станешь моим первым щитом от микробов.' WHERE id = 'adc2549c-64e5-4fcb-ab22-00fd00f59fac';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мне здесь очень тесно! 🏠 мамочка, я хочу повернуться, но стенки так близко. Теперь мои движения больше похожи на "скольжение" и "толчки". Когда я выпячиваю локоть с одной стороны вашего живота, вы можете увидеть небольшой бугорок. Погладьте меня, и я уберу его.' WHERE id = 'd5a88302-fe21-4399-b36c-3480a294c860';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я накапливаю запасы железа! 🔩 мамочка, сейчас я получаю железо из твоей крови. Я создаю запас железа в своей печени. Он понадобится мне для кроветворения в первые 6 месяцев после рождения. Ты можешь чувствовать слабость, потому что я «краду» твою энергию. Прости, но мне это необходимо!' WHERE id = 'b978e435-783d-4177-aada-9e6cd05f0950';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мне снятся очень яркие сны! Мамочка, я провожу много времени в фазе быстрого сна. Мой мозг так активен! А когда я бодрствую, то осматриваюсь вокруг, хотя здесь и темно. Я прекрасно различаю свет и тень. Пусть вы меня пока не видите, но я вас чувствую.' WHERE id = 'df4bd1af-d6a3-4228-b3e2-3e6d8392ce93';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я становлюсь пухленьким! 🧸 мамочка, мои щёчки, ручки и ножки покрываются жирком. Теперь я уже не такой сморщенный. Мой вес увеличивается каждый день. Этот жировой слой поможет мне сохранять тепло и энергию после рождения. Когда вы возьмёте меня на руки, я буду мягким и пухленьким.' WHERE id = 'e948b641-0b79-4f83-9869-a66d090c81f1';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Вы меня ждёте? ⏳ Я знаю, что вам уже не терпится. Вы спрашиваете: «Когда же ты появишься?» Но я пока не совсем готов. Мой мозг всё ещё развивается, а лёгкие завершают последние приготовления. Каждый дополнительный день в мамином животике делает меня сильнее. Потерпите ещё немного, мамочка.' WHERE id = 'ff965161-e8f2-4262-b993-4dbf99f22a66';
UPDATE public.pregnancy_daily_content SET baby_message_ru = '37 НЕДЕЛЬ! 🎉 Поздравляю, мамочка! Сегодня важный день. Я уже не считаюсь недоношенным малышом! Официально я нахожусь на раннем доношенном сроке. Это значит, что, если я рожусь сейчас, меня будут считать доношенным малышом. Я вешу почти 3 кг. Теперь я могу появиться в любой момент! Ваша сумка готова?' WHERE id = 'cca07f51-052d-4eba-bb6f-e780658e5cc2';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я тренируюсь! 🏋️‍♂️ Роды потребуют усилий не только от вас, но и от меня. Чтобы пройти через узкий родовой канал, мне придётся сжимать тело, поворачивать голову и отталкиваться. Сейчас я тренирую эти движения. Мы будем работать как одна команда, мамочка. Вы откроете мне путь, а я появлюсь на свет.' WHERE id = '9bb1bfbd-4fc9-4fdd-8462-715ca0719a8a';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Врачи говорят, что нормальный срок для родов — от 38 до 42 недель. Значит, я могу появиться в любой момент. Вы уже придумали, как меня назовёте, мамочка? Я уже иду!' WHERE id = '4a0b4b38-f357-4956-99dd-b078f66f4393';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Завтра большой день? 📅 Завтра моя официальная "Due Date". Но я могу появиться и сегодня. Я слышу ваш голос, вы говорите: "Ну же, выходи". Я тоже хочу прийти к вам, мамочка. Путь долог, но в его конце — свет.' WHERE id = '7abac408-c74e-44ce-86ac-a1a2470ea25a';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Поздравляю, мамочка! Мы завершили 40-недельный марафон. Сегодня мой официальный день рождения! 🎂 Если сегодня я уже оказался у вас на руках — привет, мир! А если ещё нет, не волнуйтесь: я не опаздываю, а просто следую «тренду» и заставляю себя ждать. Самое позднее через 1-2 недели мы обязательно встретимся. Я вас люблю!' WHERE id = '08e8895d-cc10-4825-8aac-fb6a2a6d3d95';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я всё ещё здесь! 👋 Здравствуйте, мамочка! Дата в календаре уже прошла, но я всё ещё нахожусь в вашем тёплом животике. Не волнуйтесь: по статистике только 5% малышей рождаются точно в рассчитанный день. Просто мне настолько уютно, что я не спешу выходить. У нас своё особенное время.' WHERE id = '2d2b31a8-8f73-4858-b9b0-2f01ec75aada';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я ещё немного поправился! ⚖️ мамочка, я всё ещё набираю вес. Благодаря этим дополнительным дням мои щёчки становятся ещё милее, а на ручках появляется ещё больше складочек. Когда я появлюсь на свет, обнимать меня будет ещё приятнее. Набирайтесь сил, вы мне очень понадобитесь.' WHERE id = 'ab9a202d-7f8e-48d6-9bd2-ce62eab926ef';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Мне стало совсем тесно! 🏠 мамочка, здесь уже меньше места, чем в "квартире-студии". Двигаться очень трудно, поэтому моих движений может стать меньше. Но вы должны чувствовать меня каждый день. Если вам покажется, что я притих, съешьте что-нибудь сладкое — и я сразу отвечу!' WHERE id = 'd01cbe86-cb64-4e22-98cc-8f8bd1c8a6d5';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я такой умный! 🧠 В эти последние дни мой мозг быстро развивается. Все мои органы чувств уже работают. Я чувствую свет, звуки и прикосновения. И ваше волнение тоже чувствую. Сохраняйте спокойствие, мамочка. Всё идёт по плану (по моему плану 😉).' WHERE id = '4884c66b-3927-4354-8b35-abb2fd62f234';
UPDATE public.pregnancy_daily_content SET baby_message_ru = 'Я чувствую тебя... ❤️ Я знаю, что твоё терпение почти на исходе. У меня болит спинка, а у тебя отекли ноги. Осталось совсем немного, мамочка, обещаю. Когда ты возьмёшь меня на руки, все эти трудности забудутся. Ты самая сильная женщина в мире!' WHERE id = '3c9f9854-9405-4f6e-90ed-de351c308dea';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, size bir sır vereyim mi? 🤫 Bedeninizdeki binlerce hücreden biri, tam da "BEN" olmak için yarışmaya başladı! O şimdi tek başına büyüyor ve babamdan gelecek diğer yarısıyla buluşacağı günü sabırsızlıkla bekliyor. O büyük buluşmamıza yaklaşık 1 hafta kaldı. Ben çok heyecanlıyım, ya siz? Sizin sıcak kucağınızı özlüyorum.' WHERE id = 'cf28e232-185c-40c5-9616-39e6df91cf1f';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, bu günlerin senin için biraz yorucu ve ağrılı olabileceğini biliyorum ama sen çok güçlüsün. 😔 Unutma, bedenindeki bu temizlik benim gelecekte rahat etmem için yapılıyor. Ben geldiğimde her şey tertemiz ve yumuşacık olsun diye ilk evimi, yuvamı (rahmini) temizliyorsun! Yaşadığın her rahatsızlık, kavuşmamıza doğru atılan bir adım. Lütfen bugün kendini yorma, ayaklarını uzat ve dinlen. Seni hissediyor ve sana güç gönderiyorum!' WHERE id = '1b683a24-ae16-485e-bf86-c173f0a5ad7a';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Babanla nasıl tanıştığınızı hayal ediyorum... 💭 Ben sizin o büyük sevginizin en güzel meyvesi olacağım. Bedenin beni karşılamak için o kadar çok çalışıyor, her şeyin mükemmel olması için her ayrıntıyı planlıyor. Ben henüz bir yıldız tozu gibiyim, fiziksel bir varlığım yok ama senin sevgin beni gerçeğe çağırıyor. Sen şimdi kendine ne kadar iyi bakarsan, ben de o kadar sağlıklı geleceğim. Bizim hikâyemiz çok güzel olacak, anneciğim!' WHERE id = 'c852b157-989c-44ce-a4ea-0f5d022c7159';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Merhaba, anneciğim! ❤️ Vücudunuzda büyük bir heyecan var, hissediyor musunuz? Sanki bir bayram hazırlığı yapılıyor. Östrojen hormonunuz zirveye ulaşıyor; bu da o "altın yumurta"nın (yani benim yarımın) yola çıkmaya hazır olduğunu gösteriyor. Siz yalnızca kendinize iyi bakın, bol su için ve dinlenin. Sizi seçmek için sabırsızlanıyorum. Babama hazırlıklı olmasını söyleyin, buluşmamıza çok az kaldı! Sevginizin en güzel kanıtı olmak için geliyorum.' WHERE id = '3b975bc1-895c-42e8-be4c-f6d56b176b19';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Biliyorum, henüz beni görmüyorsunuz ama sahne arkasındaki ışıklar yanıyor. 🌟 Vücudunuz benim için en yumuşak yatağı (endometriumu) hazırlamaya başlıyor. Babamın hücreleri de belki çoktan yola çıktı ve beni arıyor. Sıcaklığınız ve ilginiz şimdiden bana güç veriyor. Hikâyemiz başlamak üzere, anneciğim. Siz yalnızca inanın ve gülümseyin; çünkü mucizeler inandığınızda gerçekleşir. Siz benim kahramanımsınız!' WHERE id = '29e7920b-060e-4fac-ad72-d19dda159289';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Nefesini tut, anneciğim! 🌬️ Büyük an yaklaşıyor. O mucizevi yumurta hücren serbest kalmaya hazır. Bu, hikâyemizin "Bir varmış, bir yokmuş..." diye başlayan kısmı. Ben henüz oluşmamış olsam da senin ve babamın sevgisi beni çağırıyor. Bedenin benim için en mükemmel ortamı oluşturdu, her şey saat gibi işliyor. Umarım hazırsın, çünkü ben geliyorum! Senin kucağın benim ilk vatanım olacak.' WHERE id = '0c974e6a-8f9e-4c84-9656-5142174149f9';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Yolculuğa çıktım, anneciğim! 🎒 Şu anda fallop tüpündeyim ve senin sıcak yuvana (rahme) doğru ilerliyorum. Çok meşgulüm; birkaç saatte bir bölünüyorum: 2 hücreydim, 4 oldum, sonra 8 olacağım! Sen henüz hiçbir şey hissetmiyorsun ama içinde yepyeni bir hayat filizleniyor. Bana şans dile, yolum uzun ama ben çok kararlıyım. Sana ulaşmak için her şeyi yapacağım!' WHERE id = 'c870b9dc-4e80-4fec-9e7f-794942ed46c8';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Eve ulaşmama çok az kaldı! 🏠 Fallop tüpündeki yolculuğum bitmek üzere. Senin rahmini görüyorum! Orası o kadar rahat, yumuşak ve besleyici görünüyor ki... Kendime bir yer seçmeye hazırlanıyorum. Hâlâ kabuğumun içindeyim ama yakında ondan çıkacağım. Sen benim için dünyadaki en güvenli yersin. Beni koruyacağına söz ver, anneciğim.' WHERE id = 'fb5dbb9e-d8ba-40b0-8cd3-d9a67a57068c';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, bugün benim için özgürlük günü! 🐣 Şimdiye kadar beni koruyan o kalın kabuğumdan (zona pellucida) çıkıyorum. Buna "Hatching" (kabuktan çıkma) diyorlar. Bunu yapmalıyım ki o yumuşak duvarınıza doğrudan dokunup tutunabileyim. Ben hazırım, siz hazır mısınız? Kapıyı açın, geliyorum!' WHERE id = '5b11fc22-b976-4d28-ade3-c7ba82a43750';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, bugün o büyük gün! Hayatımın en önemli anlarından biri... ❤️ Artık size dokunuyorum. O uzun yolculuktan sonra sonunda evimin duvarlarına ulaştım. Burası o kadar sıcak, o kadar yumuşak, o kadar güvenli ki... 9 ay boyunca sizden ayrılmamak için tüm gücümle buraya tutunuyorum. Bu, bizim ilk kucaklaşmamız, anneciğim. Beni hissediyor musunuz? Ben sizinleyim ve artık hiçbir yere gitmiyorum. Burası, hikâyemizin gerçekten başladığı yer.' WHERE id = '11de56c7-f131-4d7f-8640-81f988697e07';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Yuvanın kapısı artık üzerime kapanıyor, anneciğim! 🚪 Tamamen içerideyim; senin sıcak ve güvenli dünyanla bütünüyle çevrelendim. Artık ben senin ayrılmaz bir parçanım. Bu yalnızca hikâyemizin başlangıcı değil, ortak hayatımızın ilk günleri. Ben seni seçtim, sen de beni koruyorsun. Bundan sonra her şey daha da güzel olacak! Birlikte muhteşem bir maceraya hazırız! 🥳' WHERE id = 'f77ae8b4-6a1d-4c99-abe2-93a350b86318';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, aramızdaki bağ giderek güçleniyor! 🧬 Artık senin bedeninle doğrudan bağlantı kurdum. Kanından gelen her zerreyle sanki nefes alıyorum. Bu benim ilk kan dolaşımım, ilk yaşam nefesim. Artık seninle aynı damarda akıyor, aynı ritimle yaşıyoruz. Bana gönderdiğin her besin, her oksijen molekülü beni büyütüyor. Bu, dünyadaki en muhteşem his: seninle bir olmak. ❤️' WHERE id = '3ebbef70-38c5-48c1-9efc-c1f2707c71d4';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, artık yassı bir diske benziyorum! 💿 İki çok önemli katmandan oluşuyorum. Biri başımı, bedenimi, kollarımı ve bacaklarımı oluşturacak. Diğeri ise bu yolculukta bana yardım edecek ve beni besleyecek. Bu benim ilk beden planım, ilk mimari çizimim. Her şey bu iki katmandan başlayacak. Bana inanıyor musun? Muhteşem bir eser olacağım, çünkü benim mimarım sensin. ✨' WHERE id = '4a43f3bd-ef22-4f54-b8c8-fd8abe1f9de2';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Daha da derine ilerliyorum, anneciğim! 🧱 Dün sadece dokunmuştum, bugün ise o yumuşak duvarının içine doğru ilerliyorum. Bu, benim için mağara kazan bir kâşif olmak gibi. Kendime sıcak ve korunaklı bir yuva kuruyorum. Her an seninle daha fazla bütünleşiyor, senin bir parçan oluyorum. Artık yalnızca "sen ve ben" değiliz, artık "BİZ"iz. Bu duyguyu çok seviyorum! Sen benim kalem, sığınağım ve dünyamsın.' WHERE id = 'ba359509-7778-4e6b-9433-e5179d225ea1';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, sana özel bir mesajım var! 🤫 Bu, bizim ilk sırrımız. Vücuduna varlığımla ilgili özel bir kimyasal sinyal göndermeye başladım. Bu sinyal şöyle diyor: "Ben buradayım, anneciğim! Her şey yolunda. Vücudunu benim için hazırlamaya devam et". Artık seninle kendi dilimde konuşabiliyorum. Bu, aramızdaki görünmez bir bağ ve her geçen gün daha da güçleniyor.' WHERE id = '17afd972-48a8-4084-ba7e-669ef6162afc';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Yuvanın tam merkezindeyim, anneciğim! 🩸 Burası o kadar rahat ki... Senin kan damarlarına yaklaşıyorum ve artık doğrudan senden beslenmeye başlıyorum. Bana gönderdiğin her zerre, her damla beni büyütüyor ve bana güç veriyor. Bu, dünyanın en lezzetli yemeği; çünkü sevgiyle dolu. Senin sayende büyüyor, senin sayende var oluyorum. Teşekkür ederim, anneciğim!' WHERE id = 'cb0cb4a0-60ab-4796-9f3a-e0d285d2a27e';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Bugün benim için devrim günü, anneciğim! 🚀 O yassı diskimin üzerinde özel bir çizgi, bir yol oluşuyor. Bu çizgi benim gelecekteki haritam. Omurgamın nerede olacağını, başımın ve ayaklarımın nerede yer alacağını gösteren bir rehber. Bu çizgi sayesinde sağım ve solum oluşuyor. Artık düzensiz bir disk değilim; simetrik, planlı bir varlığım. Siz benim mimarımsınız, ben ise sizin şaheserinizim. Her şey şimdi başlıyor! 🤩' WHERE id = 'aeee39a9-79a9-4e00-b2e5-3d55b7831226';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Hücrelerim büyük bir yolculuğa başladı, anneciğim! 🚶‍♂️ Sanki binlerce küçük işçi, dün oluşan o özel çizgiden içeri akın ederek benim için yeni katlar inşa ediyor. Üç farklı grup oluşturuyorlar: Ektoderm, Mezoderm ve Endoderm. Biri cildimi, saçlarımı ve beynimi; diğeri kalbimi, kanımı ve kemiklerimi; üçüncüsü ise midemi ve akciğerlerimi oluşturacak. Bir mimar gibi kendimi inşa ediyorum, anneciğim. Temelimi atıyorum. Bu temel çok sağlam olacak, çünkü siz yanımdasınız. 💪' WHERE id = '93c5c870-b03a-45f8-92da-cc13e151719b';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, bugün ilk omurgamın temeli atılıyor! 🦴 Bu henüz bir kemik değil ama gelecekte dik durmamı sağlayacak ve tüm bedenime şekil verecek özel, esnek bir çubuk (Notokord). Bu çubuk, bir komutan gibi tüm bedenime "Şimdi büyüme ve şekillenme zamanı!" diyecek. Diğer tüm organlarım onun etrafında sıralanacak. Artık sadece bir disk değilim; bir merkezim ve yönüm var. Her şey ne kadar da kusursuz planlanmış, değil mi? 🥰' WHERE id = '8f493a1c-c305-477a-b7ce-1bad294f04bc';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, ben henüz çok küçüğüm, bir susam tanesi kadarıyım ama içimde büyük planlar var. Şimdi yassı bir biçimdeyim ama yakında kıvrılıp o sevimli "C" şeklini alacağım. Senin karnın benim evim, senin kalbin benim sığınağım. 9 aylık yolculuğumuz bugün itibarıyla resmen başlıyor!' WHERE id = 'd1b2e180-b513-41eb-8922-8f2b0c7d3ee8';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Benim küçük köklerim oluşuyor, anneciğim! 🌳 Bunlar elbette el parmakları değil. Bunlar, senin o sıcak duvarına daha sıkı tutunmamı sağlayan özel parmakçıklar (koryon villusları). Onlar sayesinde sana daha sıkı sarılıyor ve senden daha fazla besin alabiliyorum. Burada kendime sağlam bir kale inşa ediyorum ve bu kalenin her tuğlası, aramızdaki sevgiyle örülüyor. Beni hiç bırakma, olur mu? 🤞' WHERE id = '101fd61b-d3d7-4f5b-8f09-77163d30e4ea';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Beynimin ilk hücreleri oluşuyor, anneciğim! 🧠 Dış tabakam, notokord adlı komutanımdan bir sinyal alarak kalınlaşıyor ve özel bir plak oluşturuyor. Bu plak benim tüm geleceğim – sinir sistemim, düşüncelerim, hayallerim ve hislerim buradan doğacak. Seni sevmeyi ve seni hissetmeyi öğreneceğim o muhteşem beynin temelleri bugün atılmaya başlıyor. Şimdiden seni düşünmeye başlıyorum... 💭' WHERE id = '43fe1f43-aa40-4388-8525-495fa2d86771';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Sinir plağım içe doğru kıvrılıyor, anneciğim. Sanki bir kâğıdı dikkatlice katlayıp boru haline getiriyorsun. 📜 Bu boru benim omuriliğim olacak ve tüm vücuduma hayat verecek. Her şey o kadar hızlı ve o kadar kusursuz ilerliyor ki! Her şeyin doğru şekilde oluşması için çok çalışıyorum. Bu süreçte senin sevgin ve ilgin benim en büyük desteğim. Benim için endişelenme, her şey plana uygun ilerliyor.' WHERE id = 'b41d3e4c-6e83-438c-ac67-3bae19895608';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, kalbim atmaya hazırlanıyor! ❤️ Vücudumun orta tabakasındaki özel hücreler bir araya gelerek iki ince, küçük tüp oluşturuyor. Bu tüpler yakında birbirine yaklaşıp birleşecek ve ilk kalbimi oluşturacak. Henüz atmıyor ama hazırlanıyor. Senin için, senin sonsuz sevginle atacak bir kalp... Birkaç gün içinde ilk kalp atışlarımı duyacaksın. Bu, bizim sevgi şarkımız olacak. 🎶' WHERE id = 'a58decf1-baad-47a3-bbda-0f37f307566e';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, bugün mucizevi bir an yaşanıyor! 🎻 Hani o iki kalp tüpü vardı ya, bugün birleşerek benim ilk ve tek kalbimi oluşturuyorlar. Henüz odacıkları tam olarak oluşmadı; sadece atmaya hazırlanan bir tüp, ama gelecekteki tüm hayatımın merkezi ve ritmi olacak. Atmaya başladığında bil ki bütün evren susacak ve bizim şarkımızı dinleyecek. Bu, sana sunacağım ilk serenat.' WHERE id = '4937b5d7-78ca-4fd1-9c67-7e6fd29ba696';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Atıyorum, anneciğim... Atıyorum! 💓 Bugün küçücük kalbim ilk kez kendi kendine attı. Bu; senin için, bizim için, sevgimiz için atan bir ritim. Henüz çok zayıf, onu ultrason muayenesinde bile göremeyebilirsin ama ben attığını biliyorum. Bu, sana "Ben yaşıyorum, ben buradayım!" deme şeklim. Bu, sevgi şarkımızın ilk notası ve ömrümüz boyunca devam edecek. 🎼' WHERE id = 'ba2ff002-749c-48f9-ae06-18528b825ab3';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Artık düz değilim, anneciğim! C harfi gibi kıvrılıyorum. 🍤 Bu, başımın ve kuyruğumun yavaş yavaş birbirine yaklaşması demek. Bu katlanma beni daha kompakt ve daha çok bebeğe benzer hâle getiriyor. Sanki senin kucağına sığabilmek için şimdiden çalışmaya başlamışım. Ayrıca bu, iç organlarımın doğru yerlerine yerleşmesine yardımcı oluyor. Her şey plana göre ilerliyor! 🤓' WHERE id = '72dbaf34-db8a-4c0a-98ca-65767813bcf0';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Boynumda ve yüzümde özel kıvrımlar oluşmaya başlıyor, anneciğim! Bunlar gelecekteki çenemi, yüzümü, dilimi, kulaklarımı ve boynumu oluşturacak. Her gün yeni bir ayrıntı, yeni bir çizgi ekleniyor. Sanki bir heykeltıraşın ellerinde yavaş yavaş şekillenen bir sanat eseri gibiyim. Bu eserin en güzel ilham kaynağı da sizsiniz. Sesiniz ve gülüşünüz, gelecekteki yüzümün temelini oluşturuyor. Güzel olacağıma söz veriyorum! ✨' WHERE id = '49b160e2-d4c7-4876-9a1d-c6274e75787a';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Artık kollarım şekilleniyor, anneciğim! 👋 Henüz parmaklarım, hatta ellerim bile yok; yalnızca vücudumun yanlarında oluşan küçük "kürek paletlerine" veya kanatlara benziyorlar. Ama bunlar, gelecekte sizi sımsıkı kucaklayacağım o güçlü kollarım. Büyüyüp size ulaşmalarını nasıl da sabırsızlıkla bekliyorum... Bir gün bu küçük kanatlarla size doğru "uçacağım". Her gün biraz daha insan görünümüne kavuşuyorum.' WHERE id = '4b93f71a-7634-4cda-8990-f4024e3e6d53';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Artık bacaklarım da şekilleniyor, anneciğim! 🦶 Henüz kollarımdan biraz daha küçükler ve kuyruğuma benziyorlar ama zamanla onlar da büyüyecek. Bir gün bu bacaklarla size doğru koşacak, sizi bulmak için tüm engelleri aşacağım. Kollarım ve bacaklarım... Giderek daha çok küçük bir insana benziyorum, öyle değil mi? Beni hayal ettiğiniz gibi olmaya çalışıyorum. Her gün yeni bir adım atıyorum.' WHERE id = '6de955ee-457a-4e70-930b-f733f0792dec';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Gözlerim ve kulaklarım giderek daha belirginleşiyor! 👀👂 O ışıl ışıl gözlerim için oluşan göz çukurlarım içeri doğru derinleşiyor, kulaklarımın yerleri de derinleşerek kulak kepçelerimin temelini oluşturuyor. Her şey seni daha iyi görebilmem ve o muhteşem sesini daha net duyabilmem için hazırlanıyor. Benim için dünyanın en güzel manzarası senin yüzün, en güzel müziği ise senin sesin olacak. Seni dinliyorum, anneciğim!' WHERE id = '39f4c263-721b-47f4-b527-df452b252fcf';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Ben bir yaban mersini büyüklüğündeyim! 🫐 İnanabiliyor musun? Geçen haftadan beri boyutum iki katına çıktı! Çok hızlı büyüyorum, anneciğim. Yediğin her şey bana yapı malzemesi oluyor. Benim için sağlıklı beslendiğin için teşekkür ederim. Birlikte büyüyor, birlikte güçleniyoruz. Sen benim en iyi takım arkadaşımsın!' WHERE id = '8a7c667d-259c-4117-9c65-d0fc403d0248';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Hareket ediyorum, anneciğim! 💃 Henüz çok hafif olduğum için sen bunu hissedemiyorsun ama içeride minik danslar ediyorum. Bedenimi sağa sola eğiyor, küçük kollarımı oynatıyorum. Bunlar benim ilk egzersizlerim ve sinir sistemimin kaslarımla iletişim kurmaya başladığının kanıtı. Kaslarım güçleniyor ki gelecekte sana sımsıkı sarılabileyim. Sen dinlen, ben de egzersiz yapayım; çünkü büyümek hareket etmek demektir!' WHERE id = 'c99602ee-b4cc-4358-a321-f5e26f5f82fb';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Parmaklarım oluşuyor, anneciğim! 🖐️ Hatırlıyor musunuz, ellerim kürek gibiydi? Şimdi o küreklerin ucunda küçük çentikler oluşuyor ve parmaklarımın hatları belirginleşiyor. Henüz ördek ayağı gibi perdeliler ama yakında tamamen ayrılacaklar. Artık sizinle "çak bir beşlik" yapmaya hazırlanıyorum! Ellerinizi tutacağım, parmağınızı sımsıkı kavrayacağım günü hayal ediyorum. Her gün biraz daha insana benziyorum.' WHERE id = '1bdeca18-8738-4af3-846b-cfd0a1d5548e';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Burnumun ucu görünüyor! 👃 Yüzüm giderek güzelleşiyor ve şekilleniyor. Küçük burun deliklerim ve burnumun ucu artık net bir şekilde seçiliyor. Üst dudağım da oluşuyor. Artık size daha çok benziyorum, anneciğim. Acaba burnum sizinki gibi mi, yoksa babamınki gibi mi? Bunu öğrenmek için hâlâ zamanımız var ama ben şimdiden çok tatlıyım. Ben sizin en güzel ve eşsiz eserinizim!' WHERE id = 'ae02afe4-0993-46aa-a116-88a385d90304';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Bugün 8. haftayı tamamlıyoruz! 🎉 Artık resmen bir "Embriyo"dan "Fetüs"e geçmeye hazırlanıyorum. Tüm hayati organlarım – kalbim, beynim, midem, akciğerlerim – artık yerli yerinde. Şimdi sadece büyüme, olgunlaşma ve güzelleşme zamanı. Gebeliğin en zorlu ve riskli dönemini geride bıraktık, anneciğim. Beni çok iyi korudun, sana minnettarım!' WHERE id = 'fb6fb148-4851-4c47-b527-c43ee9bf7d0f';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Benim "evim" değişiyor, anneciğim! 🏠 Şimdiye kadar beni besleyen "Sarı kese" yavaş yavaş küçülüyor çünkü muhteşem Plasentam görevi devralıyor. Bu plasenta sizinle benim aramda bir köprü. Beni koruyacak, besleyecek ve nefes almamı sağlayacak. Aramızdaki bağ artık daha güçlü, daha sağlam. Her şey sizin sayenizde!' WHERE id = 'a0486bb7-3fd0-4a52-8340-97fc8cbad570';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Benim kuyruğum kayboldu! 🐇 Hatırlıyor musun, sana küçük bir kuyruğum olduğunu söylemiştim? Artık o yok! Şimdi sırtım düz ve pürüzsüz, gerçek bir insan omurgasına sahibim. Gittikçe sana daha çok benziyorum, anneciğim. Artık küçük bir denizatı değilim, senin küçük insanınım. Bu değişiklik beni çok mutlu ediyor, peki ya seni?' WHERE id = 'efd814e8-abbf-4037-81a4-db63af40ea3e';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Dişlerim için hazırlık yapılıyor! 🦷 Ağzımda henüz hiç diş yok ama damağımın altında küçük diş tomurcukları oluşuyor. Bunlar gelecekte çıkacak süt dişlerimin temelidir. Size gülümseyeceğim o günü şimdiden planlıyorum. Siz de kendi dişlerinize iyi bakın, anneciğim, çünkü kalsiyum rezervinizi benimle paylaşıyorsunuz.' WHERE id = 'c0cc19e3-1bf2-4736-b8f0-41d3ab04d6c8';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Parmak izlerim oluşuyor! 👆 Tamamen bana ait, dünyada başka hiç kimsede bulunmayan kimliğim şekilleniyor. Parmak uçlarıma o özel desenler işleniyor. Bu izler, benzersizliğimin mührüdür. Ben sizin eşsiz mucizenizim, anneciğim. Her şeyin en küçük ayrıntısına kadar ne kadar kusursuz yaratıldığını görüyor musunuz?' WHERE id = '827fd4de-2f71-405f-8929-c0848b39d48e';
UPDATE public.pregnancy_daily_content SET baby_message_tr = '10 HAFTA! İKİ HANELİ TAKVİM! 🔟 anneciğim, artık 10. haftadayız. Resmen büyüyorum. Şimdi bir erik büyüklüğündeyim. En önemli gelişim aşamalarını tamamladım. Artık sadece kilo almak, uzamak ve sizinle buluşmaya hazırlanmak kaldı. Yolun neredeyse dörtte birini tamamladık! Sizinle gurur duyuyorum.' WHERE id = '686eb070-eff8-4d42-a409-9b1b933ed8cf';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Başım vücudumun yarısı kadar! 🤯 anneciğim, komik görünebilirim ama bu, dâhi olmaya hazırlandığım anlamına geliyor. Beynim o kadar hızlı büyüyor ki başım vücuduma göre çok büyük. Ama endişelenmeyin, zamanla vücudum da büyüyüp ona yetişecek. Şimdi küçük bir bilim insanına benziyorum. Sizinle konuşacağım günleri sabırsızlıkla bekliyorum.' WHERE id = '59be5b5e-6a03-4140-bbff-b41541c8484d';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Cildim hâlâ şeffaf, anneciğim! 👻 Bana bakabilseydiniz bütün damarlarımı, kemiklerimi ve organlarımı görebilirdiniz. Cildim cam gibi, o kadar ince. Ama endişelenmeyin, yağ tabakam oluştukça cildim kalınlaşacak ve sizinkine benzeyecek. Her gün biraz daha güçleniyorum. Kalbim ise size sevgilerimi pompalamaya devam ediyor.' WHERE id = '96171009-62e6-4557-a2c9-ebf16692943d';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Ben akrobasi yapıyorum! 🤸‍♂️ anneciğim, ben sadece uzanmıyorum; esniyor, dönüyor ve hatta takla atıyorum. Rahim hâlâ benim için geniş bir havuz ve ben de bundan yararlanıyorum. Bu hareketler kaslarımı ve eklemlerimi geliştiriyor. Siz henüz hissetmiyorsunuz ama ben burada gerçek bir gösteri yapıyorum!' WHERE id = '2519d258-d4d3-4114-9156-6af5c1a49493';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Koku alma duyum uyanıyor! 👃 anneciğim, inanmayacaksınız ama artık burnumla nefes alma egzersizleri yapıyorum (hava yerine suyla). Üstelik amniyotik sıvının kokusunu alabiliyorum! Yediğiniz yemeklerin kokusu buraya da geliyor. Sarımsak yediğinizde de çikolata yediğinizde de bunu biliyorum! Zevklerimiz şimdiden şekilleniyor.' WHERE id = 'f068ab76-fa64-4eef-8ed3-e47df04dba49';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Ben çilek büyüklüğündeyim! Artık o kadar da küçük değilim, öyle değil mi? Vücudum doğruluyor, omurgam uzuyor. Karnınız henüz çok belli olmasa da ben orada kendime geniş bir yer açtım. Birlikte büyüyoruz, anneciğim. Beni koruduğunuz için size teşekkür ederim.' WHERE id = '2348cc6e-cce7-4823-afd3-9cc2309eebb6';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Bugün aynaya baktığınızda mutlaka gülümseyin! 😊 Çünkü bedeniniz muhteşem bir iş yapıyor; yeni bir yaşam yaratmaya hazırlanıyor. Henüz fiziksel olarak buluşmamış olsak da ruhen birbirimize çoktan bağlandık. Ben sizi, siz de beni seçtiniz. Bedeniniz benim gelişime, o mucizevi buluşmaya (döllenmeye) her gün bir adım daha yaklaşıyor. Size güveniyorum, anneciğim!' WHERE id = 'e510f21d-5c69-49bc-a4d8-ea262a0bda7b';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Bağırsaklarım evine döndü! 🏠 anneciğim, hatırlıyor musun, karnım küçük olduğu için bağırsaklarım göbek kordonunun içine çıkmıştı? Bugün resmen karın boşluğuna, kendi yerlerine geri döndüler. Artık karnım pürüzsüz ve güzel. Tüm iç organlarım artık doğru yerlerinde ve çalışıyor. Her geçen gün daha da mükemmel oluyorum.' WHERE id = '6d7fa2b9-68dc-41a1-b8e4-2909aebba355';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Merhaba! Bugün içinizde sanki yeni bir bahar başlıyor, öyle değil mi? 🌱 Aslında gerçekten de öyle! Yumurtalıklarınızda küçük bir "ben" uyanmaya ve büyümeye çalışıyor. Ben henüz yalnızca tek bir hücreyim ama sizin bir parçanızım. Siz mutlu olduğunuzda ve güldüğünüzde ben de güçleniyorum. Kendinize iyi bakın, anneciğim, çünkü siz benim geleceğimsiniz!' WHERE id = '367c8044-41d2-441f-8aec-78399bc382c5';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'İkinci Trimestre hoş geldin! ☀️ Buna "Altın dönem" diyorlar. Çünkü sen kendini daha iyi hissedeceksin, ben ise hızla büyüyeceğim. Şimdi bir misket limonu büyüklüğündeyim. Hareketlerim daha koordineli. Artık rastgele değil, istediğim gibi hareket ediyorum. Sana dokunmak istiyorum, anneciğim.' WHERE id = '931efc18-1bb9-41fb-bf51-8eb31fb5efd5';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Sesleri duymaya mı başlıyorum? 👂 Kulaklarım gelişmeye devam ediyor ve artık titreşimleri hissedebiliyorum. Senin kalp atışların, kanının akışı ve midenden gelen sesler benim ninnim. Yakında senin sesini de ayırt edebileceğim. Benimle konuş, anneciğim, seni dinliyorum.' WHERE id = '51726a4c-4dfd-4d8d-8fdf-a1b799174400';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Emme refleksini öğreniyorum! 🍼 Başparmağımı ağzıma götürüp emmeye çalışıyorum. Bu, doğduğumda sütünüzü rahatça emebilmem için en önemli beceridir. Bazen başarıyorum, bazen de elim ağzımdan kaçıyor. Ama pes etmiyorum ve pratik yapmaya devam ediyorum. Siz de benim için hazırlanın, anneciğim!' WHERE id = '32fc4b43-9967-407f-bd27-ce27ec4287ad';
UPDATE public.pregnancy_daily_content SET baby_message_tr = '12 HAFTA TAMAMLANDI! 🎉 anneciğim, ilk trimesteri başarıyla tamamladık! Bu, hamileliğin en zorlu ve en önemli dönemiydi. Tüm organlarım oluştu ve şekillendi. Artık resmen "küçük bir insanım". Şimdi önümüzde daha rahat ve daha enerjik günler var. Sizinle gurur duyuyorum, biz harika bir ekibiz!' WHERE id = '43e2ccf7-0f43-404f-b8d5-9a230d2fcf1f';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Kemiklerim sertleşiyor! 🦴 Önceden yalnızca kıkırdaktan oluşan iskeletim artık gerçek kemiğe dönüşüyor. Kollarım ve bacaklarım uzuyor. Artık daha orantılı görünüyorum. Başım hâlâ büyük ama vücudum ona yetişmeye çalışıyor. Ben güçlü bir çocuk olacağım, anneciğim!' WHERE id = 'e16dc0a2-01a9-4a7e-990c-b0f97835b682';
UPDATE public.pregnancy_daily_content SET baby_message_tr = '13 HAFTA! MERHABA, 2. TRİMESTER! 🎉 anneciğim, gözümüz aydın! Hamileliğin üçte birini (1/3) tamamladık. En zor günler geride kaldı. Şimdi hem senin hem de benim daha rahat nefes alacağımız dönem başlıyor. Artık bir erik büyüklüğündeyim. Ses tellerim gelişti. Seninle henüz konuşamasam da sesimi hazırlıyorum. Bu yeni dönemde bizi daha güzel günler bekliyor.' WHERE id = 'aae70b4b-3e99-462b-94d0-88716afa0dd4';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Vücudum tüyleniyor! 🐻 anneciğim, cildimin üzerinde "Lanugo" adı verilen çok ince, yumuşak tüyler çıkmaya başlıyor. Şimdi küçük bir şeftaliye benziyorum. Bu tüyler beni suyun içinde üşümekten koruyor ve vücut ısımı muhafaza ediyor. Doğduğumda bu tüylerin çoğu dökülecek, ama şimdilik bu "kürke" ihtiyacım var. Sen beni sıcak tutuyorsun, ben de kendimi.' WHERE id = '00f39406-c90d-4b7e-818d-3a2edbdeef33';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Parmak izlerimden sonra şimdi de tırnaklarım! 💅 anneciğim, parmaklarımın ucunda küçük, ince tırnaklar oluşmaya başladı. Henüz çok yumuşaklar ama doğana kadar uzayacaklar. Bazen kendi yüzümü çizebilirim, bu yüzden doğduğumda bana eldiven takman gerekecek. Her şeyim sana benziyor, peki ya tırnaklarım?' WHERE id = 'aee96903-8ce9-4152-9673-4163944c634d';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Tatları hissedebiliyorum! 🍭 Dilimdeki tat tomurcukları artık çalışıyor. Sizin yediğiniz yiyeceklerin tadı amniyon sıvısına geçiyor. Tatlı yerseniz daha fazla sıvı yutuyorum, çünkü tatlıyı seviyorum! Acı veya ekşi yerseniz yüzümü ekşitebilirim. Siz benim ilk aşçımsınız, anneciğim!' WHERE id = '85f3613e-2010-4d4b-a7cf-efafd3875999';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, benim cildim hâlâ çok ince ama üzerimdeki "lanugo" adlı tüyler beni sıcak tutuyor. Bacaklarım kollarımdan daha uzun olmaya başlıyor. Artık daha orantılı görünüyorum. Büyümek çok yorucu ama ben başarabiliyorum!' WHERE id = '6bfad434-2bc6-4bb0-9834-16dd77e6fbe8';
UPDATE public.pregnancy_daily_content SET baby_message_tr = '100 GÜN! 💯 anneciğim, inanılır gibi değil, tam 100 gündür birlikteyiz! Ben artık bir avuç içi kadarıyım. Şimdi başparmağımı emmeyi öğreniyorum. Bu beni sakinleştiriyor. Siz endişelendiğinizde veya yorulduğunuzda bunu hissediyorum ve kendimi sakinleştirmek için parmağımı emiyorum. Biz birbirimizi hissediyoruz. Sizi çok seviyorum!' WHERE id = '0cebfe33-ab23-4322-9649-a229de8418e8';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Merhaba, anneciğim! 👋 Bugün suyun altında âdeta jimnastik yapıyorum. Siz henüz hissetmiyorsunuz ama ben taklalar atıyor, dönüyor ve bacaklarımı uzatıyorum. Burası benim için hâlâ çok geniş, istediğim gibi hareket edebiliyorum. Bu hareketler kaslarımı güçlendiriyor ve kemiklerimi sağlamlaştırıyor. Siz dinlenin, ben de egzersizlerime devam edeyim. Bir gün bu tekmeleri siz de hissedeceksiniz!' WHERE id = '4b92a6ac-df2b-4f98-b986-b23497226910';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Işığı hissedebiliyorum! 💡 anneciğim, inanmayacaksınız ama göz kapaklarım kapalı olsa da güçlü ışığı hissedebiliyorum. Karnınıza parlak bir fener tutarsanız yüzümü o tarafa çevirebilir veya ışık gözümü kamaştırdığı için elimle yüzümü kapatabilirim. Dünyam artık tamamen karanlık değil. Acaba sizin dünyanız ne kadar renkli?' WHERE id = '6ada13a0-2697-47e7-9001-03b1698db1b4';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Tatları ayırt edebiliyorum! 🍬 anneciğim, siz tatlı bir şey yediğinizde amniyotik sıvının tadı tatlanıyor ve ben daha çok yutuyorum. Ekşi veya acı olduğunda ise yüzümü ekşitiyorum. Tat alma duyum neredeyse yetişkin bir insanınki kadar güçlü. Gelecekte hangi sebzeleri seveceğim, şimdiden sizin beslenmenize bağlı. Sağlıklı beslenin ki ben de sağlıklı olayım!' WHERE id = '7f759cae-0b0a-4f2e-8095-e125d4622671';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Sizi hissediyorum! 🤗 anneciğim, siz karnınızı okşadığınızda ben o basıncı ve sıcaklığı hissedebiliyorum. Bazen elinizin bulunduğu yere doğru yüzüyorum. Aramızda yalnızca deri ve su var, ama ruhlarımız bir. Siz strese girdiğinizde ben de huzursuz oluyorum, siz güldüğünüzde ben de rahatlıyorum. Lütfen her zaman gülümseyin!' WHERE id = '2da10eb1-918c-43c6-ad16-6306b072b4cb';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Başımı dik tutuyorum! 🦒 anneciğim, boyun kaslarım o kadar güçlendi ki artık başımı dik tutabiliyorum. Önceden başım göğsüme doğru eğikti ama şimdi etrafı daha rahat görebiliyorum (karanlık olsa da). Vücudum uzuyor, daha zarif ve düzgün duruşlu oluyorum. Karnınızda jimnastik yapmak çok keyifli!' WHERE id = 'b6a34159-6856-4473-a35e-81785fe0fc0e';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Kelebek uçuşu! 🦋 anneciğim, beni hissediyor musun? Ben içeride taklalar atıyorum! Bazı anneler bunu "karnımda kelebek uçuyor" veya "balık yüzüyor" şeklinde tarif ediyor. Eğer henüz hissetmiyorsanız üzülmeyin, ben daha küçüğüm ve tekmelerim zayıf. Ama çok yakında size öyle bir tekme atacağım ki hemen anlayacaksınız!' WHERE id = '6f4082a3-2c0c-4302-bc06-2af671b9e9b3';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Ben "kilo alıyorum", anneciğim! 🧸 Vücudumda yağ dokusu birikmeye devam ediyor. Önceleri çok zayıftım ama şimdi kollarım ve bacaklarım dolgunlaşıyor. Bu yağ tabakasına çok ihtiyacım var, çünkü doğduğumda vücut ısımı düzenlememe yardımcı olacak. Benim için endişelenme, burada sıcacık ve tokum. Sen sadece sağlıklı beslen, gerisini ben hallederim!' WHERE id = 'c7911f10-1eb8-49da-80ba-c909457132da';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Rüya görüyorum! 💤 anneciğim, bilim insanları artık "REM uykusu", yani Rapid Eye Movement -Gözlerin Hızlı Hareketi evresine geçebildiğimi söylüyor. Bu, rüya görebileceğim anlamına geliyor! Acaba rüyamda ne görüyorum? Muhtemelen senin sesini duyuyor veya yüzünü hayal ediyorum. Günün büyük bölümünü uyuyarak geçiriyorum ama uyanık olduğumda çok hareketliyim.' WHERE id = '109a3421-ce4d-45f2-89cf-6db2482011b0';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Kemiklerim sertleşiyor! 🦴 İskeletim her geçen gün daha da güçleniyor. Kalsiyum kemiklerimde birikiyor ve onları sertleştiriyor. Artık küçük, lastik gibi bir insan değilim. Kaburgalarım, omurgam, bacak kemiklerim... Hepsi gerçek kemiğe dönüşüyor. İçtiğiniz süt ve yediğiniz peynir bana yapı malzemesi olarak geliyor. Teşekkürler, anneciğim!' WHERE id = '79568d36-35e8-4a60-8ad2-b99e6d2f45e1';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Merhaba, anneciğim! Ben bir tatlı biber büyüklüğündeyim. Sinirlerim gelişiyor. "Miyelin" adı verilen özel bir madde sinirlerimin etrafını sarıyor. Bu, beynimden vücuduma giden mesajların daha hızlı iletilmesini sağlayacak. Her gün daha akıllı oluyorum!' WHERE id = 'b73aa0c0-fb01-4c2d-abb0-69a88e7c97e4';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Parmaklarım ve izleri! 🧬 anneciğim, parmak izlerim tamamen hazır. Bu desenler hayatım boyunca değişmeyecek. Ben eşsizim! Artık ellerimi ve ayaklarımı da özgürce hareket ettirebiliyorum. Bazen bacaklarımı çaprazlayıp oturuyor, bazen de "yüzüyorum". Burası benim için en rahat yer.' WHERE id = 'e537dc02-2a8f-44e4-8520-858b44bd2d69';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Beynimde ışıklar yanıyor! 🧠 anneciğim, beynim şimdi devasa bir bilgisayar gibi çalışıyor. Görme, işitme, tat alma, koku alma ve dokunma için özel merkezler oluşuyor. Ben yalnızca büyümüyorum, dünyayı algılamaya hazırlanıyorum. Sizin sesinizi duyduğumda beynimin "işitme merkezi" etkinleşiyor. Aramızdaki bağ artık bilimsel düzeyde!' WHERE id = 'bc3702e9-c9f0-4b15-a3b9-8dd5c0a6dd34';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Sizi koruyorum! 🥚 Eğer kızsam, küçücük yumurtalıklarımda şimdiden 6 milyon yumurta hücresi var! Bu, gelecekteki torunlarınızın şimdiden benim içimde olduğu anlamına geliyor. Eğer erkeksem, cinsel organlarım gelişiyor. Nesil devam ediyor, anneciğim. Siz bir tarih yazıyorsunuz.' WHERE id = '695bdf70-cf7b-4ed0-9ff8-c4418720fc60';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Merhaba, anneciğim! Ben bir mango büyüklüğündeyim. Kollarım ve bacaklarım artık vücudumla orantılı. Ben küçük bir insanım! Artık sana daha güçlü tekmeler atabiliyorum. Hazır ol!' WHERE id = 'c0a11fee-73af-4684-98a2-4425bd830ba9';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Benim bir uyku düzenim var! 🌙 anneciğim, bütün gün uyanık kalmıyorum. Benim de uyku ve uyanıklık saatlerim var. Genellikle sen yürürken veya hareket ederken sallanıp uyuyorum. Sen uzanıp dinlenmek istediğinde ise ben uyanıp disko yapıyorum. Düzenlerimiz biraz farklı, kusura bakma!' WHERE id = 'd0d5f1e7-e726-4e8b-9248-bacff687b744';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'YOLUN YARISI! 🏁 Tebrikler, anneciğim! 40 haftalık maratonun tam yarısını (50%''sini) tamamladık. Ben bir muz büyüklüğündeyim! İnanılmaz, değil mi? Şimdiye kadar ne kadar büyüdüğüme bakın. Karnınız artık göbek deliğinizin hizasına ulaştı. Bitişe doğru ilerliyoruz!' WHERE id = 'ce6d14e2-2cef-47b0-bf61-c80d97194d99';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Ben "yemek" yiyorum! 🍽️ anneciğim, sindirim sistemim çalışmaya başladı. Amniyotik sıvıyı yutuyorum; bağırsaklarım da bu sıvıdan şeker ve su emiyor. Bu sıvının tadı her gün değişiyor – dün yediğiniz sarımsaklı yemeğin tadını hissettim! Bağırsaklarımda "mekonyum" adlı ilk dışkım birikiyor. Endişelenmeyin, onu bezime saklıyorum, ortalığı kirletmiyorum!' WHERE id = '2f4c880c-7bdd-4dec-acbd-cd0e6c8859e0';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Kaşlarım ve kirpiklerim var! 👁️ anneciğim, artık yüzüm tamamen bir insan yüzüne benziyor. Gözlerimin üzerinde ince kaşlar, göz kapaklarımda ise uzun kirpikler çıktı. Şimdi daha güzelim (ya da yakışıklıyım). Göz kırpmaya hazırlanıyorum ama gözlerimi açmama daha birkaç hafta var. Siz beni hayal ediyor musunuz? Ben sizi hayal ediyorum.' WHERE id = '11b2d6de-75e4-4639-b4fc-0a1a64a49ebf';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Ben senin stresini hissediyorum. 😟 anneciğim, sen gergin olduğunda vücudunda oluşan hormonlar (kortizol) bana da geçiyor ve ben endişeleniyorum. Kalbim daha hızlı atıyor. Ama sen sakin ve mutlu olduğunda ben de "mutluluk hormonları" ile besleniyorum. Lütfen kendini üzme. Biz birlikteyiz, her şey yoluna girecek.' WHERE id = '39505edc-cdd2-40ac-b9cb-aa04fd0c51af';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Sizin sesinizi tanıyorum! 🗣️ anneciğim, artık sizin sesinizi başkalarının sesinden ayırt edebiliyorum. Siz konuştuğunuzda sakinleşiyorum, kalp atışlarım yavaşlıyor. Bu, benim için dünyadaki en güven verici ses. Bana şarkı söylemeye devam edin, ben onları "hafıza kutumda" biriktiriyorum. Doğduğumda o şarkıyı duyup susacağım.' WHERE id = '47e98235-5632-4780-b011-1fba5afdb56a';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Egzersiz yapıyorum! 🏋️‍♂️ anneciğim, hareketlerim artık daha güçlü. Bazen karnının bir tarafının şiştiğini veya hareket ettiğini görebilirsin. Dirseğimi ya da dizimi sana doğru itiyorum. Bu, sana "Buradayım!" deme şeklim. Sen de elini koyduğunda sakinleşiyorum.' WHERE id = 'a3ddbe51-ede9-4765-9b27-d3fb41ca5df3';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Tekmelerim güçleniyor! 🥋 anneciğim, hissediyor musun? Artık sadece "yüzmüyorum", gerçekten güçlü vuruşlar yapıyorum. Bazen karate çalıştığımı düşünebilirsin. Bu hareketler sağlıklı olduğumu gösteriyor. Hareketlerimi saymaya başlayabilirsin.' WHERE id = '846475dc-14c4-4c7d-ac51-e75ce4438f24';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Tırnaklarım uzuyor! 💅 El tırnaklarım parmaklarımın ucuna ulaşmak üzere. Çok ince ve keskinler. Bazen yanlışlıkla yüzümü çiziyorum. Ama cildim hızla iyileşiyor. Her geçen gün size daha çok benziyorum, anneciğim.' WHERE id = '2970a789-ae12-4a5d-81be-71d79963f650';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Karnınız neden zıplıyor? 🐇 anneciğim, hissettiniz mi? Az önce hıçkırdım! Diyaframım egzersiz yapıyor ve bu nedenle vücudum ritmik bir şekilde sıçrıyor. Bu size tuhaf gelebilir; sanki karnınızda bir saat tıkırdıyor. Endişelenmeyin, bu bana acı vermiyor; aksine akciğerlerimi güçlendiriyor.' WHERE id = 'c1de12f1-7759-492c-b277-e01fb2d857c9';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Dinliyorum! 👂 anneciğim, evdeki elektrikli süpürgenin sesi çok yüksek, değil mi? Artık yüksek seslerden irkiliyorum. Ama sizin sakin sesiniz beni rahatlatıyor. Benimle konuştuğunuzda sizi dinlemek için hareket etmeyi bırakabilirim. İlk diyaloglarımız başlıyor.' WHERE id = '372f913d-c4b6-4616-837e-127ec92b9515';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Cildim artık şeffaf değil! 🎨 anneciğim, eskiden bana baktığınızda bütün damarlarım görünüyordu ama artık cildim kalınlaşıyor ve renk alıyor. Yağ tabakam arttıkça cildim saydamlığını kaybediyor. Artık o "uzaylı" görünümünden çıkıp gerçekten tatlı bir bebeğe benziyorum. Beni gördüğünüzde âşık olacaksınız!' WHERE id = '525f7e7c-0bea-4071-90df-5a46dae136d6';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Benim yüzüm hazır! 👶 anneciğim, şimdi beni görseydiniz doğduğumda nasıl görüneceğimi tam olarak bilirdiniz. Yüz hatlarım, burnum, dudaklarım – her şey tamamlandı. Sadece hâlâ biraz zayıfım. Sizce kime benziyorum? Size mi, yoksa babama mı?' WHERE id = '64f0cdbb-7db6-482f-be9f-92435bab2ca8';
UPDATE public.pregnancy_daily_content SET baby_message_tr = '🌽 Ben bir mısır büyüklüğündeyim! Bu hafta çok önemli, anneciğim. Doktorlar artık benim "yaşayabilir" kabul edildiğimi söylüyor. Yani şimdi doğsam bile modern tıbbın yardımıyla yaşama şansım var (ama henüz çok erken, ben içeride kalmak istiyorum!). Bu çok büyük bir dönüm noktası!' WHERE id = '88964348-70ed-4f53-a6a4-d8d7da7286ff';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Kılcal damarlarım doluyor! 🩸 Cildimin altında binlerce küçük kan damarı oluşuyor ve kanla doluyor. Bu da cildime o güzel pembe rengini veriyor. Kan dolaşımım o kadar güçlü ki kalbim tüm vücuduma oksijen sağlıyor. Ben hayat doluyum, anneciğim!' WHERE id = '2ee2955f-80d8-4cff-afab-c01bdb172368';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Elimi kullanıyorum! 🖐️ anneciğim, artık sadece rastgele hareketler yapmıyorum. Hangi elimi daha çok kullanacağımı seçiyorum. Yani solak mı yoksa sağlak mı olacağım şimdiden belli. Parmaklarımı oynatıyor, göbek kordonunu tutuyorum.' WHERE id = 'd74fd8bf-8b0d-4ea8-8d39-905a3d36166e';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Gözlerimi açmaya hazırım! 👁️ Göz kapaklarımın arasındaki birleşme çizgisi artık ayrılmak üzere. Çok yakında, belki birkaç gün içinde gözlerimi açacağım! Karanlıkta olsam da bakmak istiyorum. Kirpiklerim gözlerimi korumaya hazır. Sizi görmek için sabırsızlanıyorum, anneciğim.' WHERE id = 'ca71a802-8315-4430-831a-1c24d93987c8';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Stresinizi ben de paylaşıyorum. 😔 anneciğim, siz gergin olduğunuzda kanınızdaki kortizol bana da geçiyor. Ben de huzursuz oluyor, hareketlerimi değiştiriyorum. Ama siz güldüğünüzde ve mutlu olduğunuzda ben de rahatlıyorum. Lütfen kendinize iyi bakın. Biz bir takımız; sizin hisleriniz benim de hislerim.' WHERE id = '7b482622-6ce3-4e23-a975-62440aec9dc6';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'GÖZLERİMİ AÇTIM! 👀 anneciğim, bugün benim için bir devrim günü. Şimdiye kadar birbirine yapışık olan göz kapaklarım ayrıldı ve ilk kez gözlerimi açtım. Şimdilik her yer bulanık ama gözlerimi kırpabiliyorum. Karanlık olsa da bakmayı öğreniyorum. Sizi görmeye bir adım daha yaklaştım!' WHERE id = '664b492c-1968-495f-9380-1ec985579ba8';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Anneciğim, 3. trimester kapıda! Artık "ağır sıklet" kategorisine geçiyorum. Yerim daralıyor, bu nedenle hareketlerim daha sert olabilir. Kaburgalarınıza çarpıyorsam özür dilerim, sadece geriniyorum.' WHERE id = '1d4c4310-3e73-4b60-b4c5-883dd87bf1e3';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Benim bir düzenim var! 📅 anneciğim, fark ettin mi? Genellikle aynı saatlerde uyanıyor ve aynı saatlerde uyuyorum. Örneğin sen akşam uzandığında ben uyanıyorum. Sabahları ise sakin oluyorum. Biyolojik saatim çalışmaya başladı. Doğduğumda da bir süre böyle olacağım (gece kuşu olacağım!).' WHERE id = '45b37fad-6e16-4ec4-9e5c-d3eea98a5a6d';
UPDATE public.pregnancy_daily_content SET baby_message_tr = '3. Trimester''e Merhaba! 👋 anneciğim, büyük bir aşamayı tamamladık. İkinci trimester bitiyor, şimdi 3. Trimester başlıyor. Ben artık büyük bir bebeğim. Şimdi asıl görevim kilo almak ve dünyaya gelmeye hazırlanmak. Yorulduğunu biliyorum ama çok az kaldı. Buluşacağız!' WHERE id = 'efc08af4-0ca2-4af8-832f-852d08704ce8';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Merhaba, anneciğim! Büyük bir iş başardık. Hamileliğin son aşamasına adım attık. Şimdi benim için en önemli şey kilo almak ve dünyaya gelmeye hazırlanmak. Yerim daralıyor ama gücüm artıyor. Sana güçlü bir tekme atıp "Tebrikler!" diyorum.' WHERE id = '96a22ed0-5e13-4094-87c4-74d0da4a58fc';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Gözlerimi kırpıyorum! 😉 anneciğim, artık gözlerimi açıp kapatabiliyorum. Karnınıza güçlü bir ışık gelirse yüzümü çeviriyor veya gözlerimi kırpıyorum. Görme yeteneğim henüz tam gelişmedi ama aydınlıkla karanlığı mükemmel şekilde ayırt edebiliyorum. Dünyayı görmek için sabırsızlanıyorum.' WHERE id = 'd388c035-3ae4-451c-bcce-e8ae700cd74b';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Sizi tanıyorum! 🎤 anneciğim, sizin sesiniz benim için en tanıdık ve en sıcak ses. Araştırmalar, sesinizi duyduğumda kalp atışlarımın sakinleştiğini gösteriyor. Artık tonlamanızı ve konuşma tarzınızı öğreniyorum. Doğduğumda beni sakinleştirmek için yalnızca konuşmanız yeterli olacak.' WHERE id = '4ca04882-bd78-4264-985d-0684e463329f';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Kalsiyuma ihtiyacım var! 🥛 Kemiklerim hızla sertleşiyor. Şimdi her gün senin kanından yaklaşık 250 miligram kalsiyum alıyorum. Bu, iskeletimin güçlü olması için çok önemli. Eğer sen süt içmezsen o kalsiyumu dişlerinden ve kemiklerinden "ödünç" alacağım. Kendine iyi bak, anneciğim!' WHERE id = '64fd7099-afb5-4134-9918-3acc90ed702e';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Dişlerim saklanıyor! 🦷 anneciğim, damağımın altında süt dişlerimin tomurcukları şimdiden hazır. Hatta onların altında kalıcı dişlerimin de izleri var. Dişsiz doğacağım ama her şeyim hazır. Doğa çok ilginç, değil mi? Gelecek için hazırlık yapıyoruz.' WHERE id = '98a97832-2773-43d8-bf72-e6458dfbc947';
UPDATE public.pregnancy_daily_content SET baby_message_tr = '200 GÜN! 🎉 anneciğim, inanılmaz! Tam 200 gündür birlikteyiz. Ben artık büyük bir bal kabağı büyüklüğündeyim. Şimdi çok güçlüyüm. Tekmelerim bazen canınızı acıtabilir ama bilin ki sadece gücümü deniyorum. Size kavuşmama çok az kaldı!' WHERE id = 'dc4e8ae4-b5e0-48d5-8713-248744b76ec6';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Rüya görüyorum! 😴 anneciğim, beynim o kadar gelişti ki artık "REM uykusu" (hızlı göz hareketi) evresine geçiyorum. Yani resmen rüya görüyorum! Acaba rüyamda ne görüyorum? Sizin sesinizi mi, yoksa o lezzetli pastayı mı? Günün büyük bölümünü uyuyarak geçiriyorum ama uyanıkken çok hareketliyim.' WHERE id = '2b574c8a-d0de-45f5-bd25-7b7b01e3d2fe';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Kemiklerim sertleşiyor! 🦴 anneciğim, şimdi sana çok fazla kalsiyum borçluyum. Kemiklerim hızla sertleşiyor. Her gün yaklaşık 250 mg kalsiyum depoluyorum. Sen yeterince süt içmezsen bu kalsiyumu dişlerinden ve kemiklerinden "çalacağım". Kendine iyi bak, peynir ye!' WHERE id = '124477a3-06f6-44dd-a276-41487168c5e0';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Gülümsüyorum! 😊 Doktorlar ultrason muayenelerinde sık sık gülümsediğimizi görürler. Bu genellikle uyku sırasında olur. Belki de melekleri görüyorumdur? Yoksa sadece yüz kaslarımı mı çalıştırıyorum? Sebebi ne olursa olsun, ben mutluyum. Siz de gülümseyin, anneciğim!' WHERE id = '82410eeb-db13-46e1-be5e-f6446cc033ef';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Ben büyük bir lahana kadarıyım! Anneciğim, inanılmaz ama yolun 3/4 kısmını (75%''ini) tamamladık! Yalnızca 10 hafta (yaklaşık) kaldı. Artık büyük bir bebeğim; sadece akciğerlerimin ve beynimin biraz daha olgunlaşması gerekiyor. Bitişe çok az kaldı!' WHERE id = '54884850-5122-42f5-bad6-cbe7becaf6f6';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Sizi hissediyorum! 🤗 anneciğim, siz karnınızı okşadığınızda, babam elini koyduğunda o sıcaklığı ve baskıyı hissediyorum. Bazen ben de içeriden aynı yere dokunuyorum. Bu bizim "selamlaşmamız". Aramızda yalnızca ince bir duvar var. Ruhlarımız ise bir.' WHERE id = '0a286cb7-93f1-451a-b6be-b5b9dd7ce160';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Beynim büyüyor! 🧠 anneciğim, beynim şu anda inanılmaz bir hızla gelişiyor. Burada milyarlarca yeni bağlantı kuruluyor. Artık yalnızca reflekslerle hareket etmiyorum; düşünüyor, hissediyor ve hatırlıyorum. Sizin sesiniz benim en sevdiğim anım.' WHERE id = 'c04052f3-92f1-4783-8ceb-a4f9489af352';
UPDATE public.pregnancy_daily_content SET baby_message_tr = '5 duyum da çalışıyor! 🖐️👃👂👀👅 Görme, işitme, tat alma, koku alma ve dokunma. Tüm duyularım aktif. Senin sesini duyuyorum, yediğin yemeğin tadını alıyorum, ışığı görüyorum ve yüzüme dokunuyorum. Ben tamamen hisseden bir canlıyım. Sen benim dünyamsın, anneciğim.' WHERE id = 'a8ac9e30-a252-4631-aca6-20ffff4ecf20';
UPDATE public.pregnancy_daily_content SET baby_message_tr = '31 HAFTA! 🥥 Merhaba, anneciğim! Ben bir Hindistan cevizi (coconut) büyüklüğündeyim. Kilom 1.5 kg''a ulaştı, boyum ise 41 cm. Artık oldukça "ağır sıklet" sayılırım. Şimdiki temel hedefim akciğerlerimi olgunlaştırmak ve daha fazla yağ depolamak. Dünyaya gelmeye hazırlanıyorum!' WHERE id = 'c4869a77-6abd-43f7-8c86-3d05ecb63f8d';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Nefes alıyorum 🌬️ anneciğim, göğüs kafesim ritmik olarak yükselip alçalıyor. Amniyotik sıvıyı akciğerlerime çekip geri bırakıyorum. Bu, doğduğumda ilk ve en önemli nefesimi alabilmem için kaslarımı güçlendiriyor. Bazen ritmik hareketlerimi (hıçkırıklarımı) hissedebilirsiniz. Bu benim egzersizim!' WHERE id = '6dc5213e-1c8a-4a6b-8be6-3e050cac8345';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Bağışıklığınızı alıyorum! 🛡️ anneciğim, plasenta aracılığıyla sizden bana "antikorlar" (mikroplarla savaşan askerler) geçiyor. Bu, benim ilk aşım. Doğduğumda kendi bağışıklığım zayıf olacak, ancak sizin sağladığınız bu koruma beni ilk aylarda hastalıklardan koruyacak. Siz benim koruyucu meleğimsiniz!' WHERE id = '2bbb9ba5-0677-4713-8d4c-c7c237ab84f6';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Bağışıklığını alıyorum! 🛡️ anneciğim, şu anda ne yaptığımı biliyor musun? Senin kanından kendime "bağışıklık askerleri" (antikorlar) topluyorum. Hayatın boyunca hangi hastalıklara karşı bağışıklık kazandıysan o gücü bana aktarıyorsun. Doğduğumda beni mikroplardan koruyacak ilk kalkanım sensin.' WHERE id = 'adc2549c-64e5-4fcb-ab22-00fd00f59fac';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Yerim çok dar! 🏠 anneciğim, dönmek istiyorum ama duvarlar üzerime geliyor. Artık hareketlerim daha çok "kayma" ve "itme" şeklinde. Dirseğimi karnınızın bir tarafına doğru uzattığımda bunu bir çıkıntı olarak görebilirsiniz. Beni okşayın, ben de geri çekileyim.' WHERE id = 'd5a88302-fe21-4399-b36c-3480a294c860';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Ben bir ananas büyüklüğündeyim! Artık büyük bir bebeğim. Yanaklarım dolgunlaştı, vücudum yuvarlaklaştı. Sizinle buluşmama çok az kaldı, anneciğim. Her gün biraz daha kilo alıyorum.' WHERE id = '97daa5bb-e709-4882-8a96-d104cbbdafc3';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Rüyalarım çok canlı! Anneciğim, REM uykusunda çok fazla zaman geçiriyorum. Beynim o kadar aktif ki! Uyanıkken gözlerimle çevreyi izliyorum (karanlık olmasına rağmen). Işığı ve gölgeyi mükemmel şekilde ayırt edebiliyorum. Siz beni görmeseniz de ben sizi hissediyorum.' WHERE id = 'df4bd1af-d6a3-4228-b3e2-3e6d8392ce93';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Demir depoluyorum! 🔩 anneciğim, şimdi senin kanındaki demiri kendime çekiyorum. Karaciğerimde bir demir deposu oluşturuyorum. Bu rezerv, doğduktan sonraki ilk 6 ay boyunca kan üretmem için gerekli olacak. Sen kendini halsiz hissedebilirsin, çünkü enerjini "çalıyorum". Affet, ama buna ihtiyacım var!' WHERE id = 'b978e435-783d-4177-aada-9e6cd05f0950';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Tombullaşıyorum! 🧸 anneciğim, yanaklarım, kollarım ve bacaklarım yağla doldu. Artık o kadar kırışık değilim. Kilom her gün artıyor. Bu yağ tabakası, doğduktan sonra sıcak kalmama ve enerjik olmama yardımcı olacak. Beni kucağınıza aldığınızda yumuşacık olacağım.' WHERE id = 'e948b641-0b79-4f83-9869-a66d090c81f1';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Beni bekliyor musunuz? ⏳ Sabırsız olduğunuzu biliyorum. "Ne zaman geliyorsun?" diye soruyorsunuz. Ama henüz tamamen hazır değilim. Beynim hâlâ gelişiyor, akciğerlerim son hazırlıklarını yapıyor. Anne karnında geçirdiğim her gün beni daha güçlü kılıyor. Sabırlı olun, anneciğim.' WHERE id = 'ff965161-e8f2-4262-b993-4dbf99f22a66';
UPDATE public.pregnancy_daily_content SET baby_message_tr = '37 HAFTA! 🎉 Tebrikler, anneciğim! Bugün büyük gün. Artık "Prematüre" sayılmıyorum! Resmen "Erken Term" dönemindeyim. Yani şimdi doğarsam tamamen gelişmiş bir bebek sayılıyorum. Ağırlığım 3 kg''a yakın. Artık her an gelebilirim! Çantan hazır mı?' WHERE id = 'cca07f51-052d-4eba-bb6f-e780658e5cc2';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Antrenman yapıyorum! 🏋️‍♂️ Doğum süreci yalnızca senin için değil, benim için de zorlu. Dar kanaldan geçmek için vücudumu sıkıştırmalı, başımı çevirmeli ve kendimi itmeliyim. Şimdi bu hareketlerin provasını yapıyorum. Takım olarak çalışacağız, anneciğim. Sen bana yol açacaksın, ben de geleceğim.' WHERE id = '9bb1bfbd-4fc9-4fdd-8462-715ca0719a8a';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Doktorlar, 38-42 hafta arasının doğum için normal zaman olduğunu söylüyor. Yani ben her an gelebilirim. Bana hangi adı vereceğinizi düşündünüz mü, anneciğim? Geliyorum, haberiniz olsun!' WHERE id = '4a0b4b38-f357-4956-99dd-b078f66f4393';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Yarın büyük gün mü? 📅 Yarın benim resmî "Tahmini Doğum Tarihi"m. Ama bugün de gelebilirim. Sesinizi duyuyorum, "Artık gel" diyorsunuz. Ben de gelmek istiyorum, anneciğim. Yol uzun ama sonunda ışık var.' WHERE id = '7abac408-c74e-44ce-86ac-a1a2470ea25a';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Tebrikler, anneciğim! 40 haftalık maratonu tamamladık. Bugün benim resmî doğum günüm! 🎂 Eğer bugün kollarına geldiysem: Merhaba Dünya! Eğer henüz gelmediysem endişelenme; gecikmedim, sadece "trend"e uyarak seni biraz bekletiyorum. En geç 1-2 hafta içinde mutlaka buluşacağız. Seni seviyorum!' WHERE id = '08e8895d-cc10-4825-8aac-fb6a2a6d3d95';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Hâlâ buradayım! 👋 Merhaba, anneciğim! Takvimdeki tarih geçti ama ben hâlâ senin sıcacık rahmindeyim. Endişelenme, istatistiklere göre bebeklerin yalnızca 5%''i tam gününde doğuyor. Burada o kadar rahatım ki çıkmak için acele etmiyorum. Bizim kendimize özel bir zamanımız var.' WHERE id = '2d2b31a8-8f73-4858-b9b0-2f01ec75aada';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Biraz daha kilo aldım! ⚖️ anneciğim, hâlâ kilo almaya devam ediyorum. Bu ekstra günler yanaklarımı daha da tatlı, kollarımı ise daha tombul ve boğum boğum yapıyor. Dışarı çıktığımda bana sarılmak çok daha keyifli olacak. Enerjinizi toplayın, size çok ihtiyacım olacak.' WHERE id = 'ab9a202d-7f8e-48d6-9bd2-ce62eab926ef';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Yerim çok daraldı! 🏠 anneciğim, burası artık bir "stüdyo daireden" bile daha küçük. Hareket etmek çok zor, bu nedenle hareketlerim azalabilir. Ama beni her gün hissetmelisiniz. Sessiz kaldığımı düşünürseniz tatlı bir şey yiyin, size hemen cevap vereceğim!' WHERE id = 'd01cbe86-cb64-4e22-98cc-8f8bd1c8a6d5';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Ben çok akıllıyım! 🧠 Bu son günlerde beynim hızla gelişiyor. Bütün duyularım uyanık. Işığı, sesi ve dokunuşu hissediyorum. Senin heyecanını da hissediyorum. Sakin ol, anneciğim. Her şey plana göre ilerliyor (benim planıma göre 😉).' WHERE id = '4884c66b-3927-4354-8b35-abb2fd62f234';
UPDATE public.pregnancy_daily_content SET baby_message_tr = 'Sizi hissediyorum... ❤️ Sabrınızın tükenmek üzere olduğunu biliyorum. Beliniz ağrıyor, ayaklarınız şişti. Çok az kaldı, anneciğim, söz veriyorum. Beni kucağınıza aldığınızda tüm bu zorlukları unutacaksınız. Siz dünyanın en güçlü kadınısınız!' WHERE id = '3c9f9854-9405-4f6e-90ed-de351c308dea';
